function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}function splitList(v){return v.split(/[,،]/).map(x=>x.trim()).filter(Boolean)}function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function renderAll(){const renderTasks=[renderRecipes,renderDashboard,renderWeek,renderPartyRecipes,renderPartyMenu,renderGuests,renderPartyChecklist,renderPartyTimeline,renderPartyEstimate,renderSavedParties,renderInventory,renderShopping,renderFamily,updateProfileOptions,renderReports];for(const task of renderTasks){try{task()}catch(error){console.error('Ghazayar render error:',error)}}}
function renderDashboard(){const meals=Object.values(state.weekly).reduce((a,d)=>a+Object.values(d||{}).filter(Boolean).length,0);$('#statMeals').textContent=fa(meals);$('#statParties').textContent=fa(state.parties.length);$('#statShopping').textContent=fa(state.shopping.filter(i=>!i.done).length);$('#statFamily').textContent=fa(state.family.length);const rows=[];for(let di=0;di<7;di++){const key=dayKey(di);const day=state.weekly[key]||{};for(const meal of MEALS){if(day[meal]){const r=recipes.find(x=>x.id===day[meal]);if(r)rows.push({day:DAYS[di],meal,r})}}}$('#upcomingMeals').innerHTML=rows.length?rows.slice(0,4).map(x=>`<div class="selected-item"><span>${x.r.emoji} <b>${escapeHtml(x.r.name)}</b> <small>· ${x.day} / ${x.meal}</small></span><button data-open-recipe="${x.r.id}">دستور پخت</button></div>`).join(''):'هنوز وعده‌ای ثبت نشده است. از بخش برنامه هفتگی شروع کنید.';const suggestion=recipes[new Date().getDate()%recipes.length];$('#dailySuggestion').innerHTML=`<span class="food-emoji">${suggestion.emoji}</span><div><b>${escapeHtml(suggestion.name)}</b><small>${escapeHtml(suggestion.description)}<br>زمان تقریبی: ${fa(suggestion.time)} دقیقه</small><button class="text-btn" data-open-recipe="${suggestion.id}">مشاهده دستور ←</button></div>`;$('#upcomingMeals').onclick=e=>{const b=e.target.closest('[data-open-recipe]');if(b)openRecipe(b.dataset.openRecipe)};$('#dailySuggestion').onclick=e=>{const b=e.target.closest('[data-open-recipe]');if(b)openRecipe(b.dataset.openRecipe)}}
function dayKey(i){const start=new Date((state.weekStart||isoToday())+'T12:00:00');start.setDate(start.getDate()+i);return start.toISOString().slice(0,10)}
function weekMealsForDay(key){return state.weekly[key]||{}}
function recipeForMeal(raw){if(!raw)return null;const exact=recipes.find(x=>x.id===raw);if(exact)return exact;const legacy=String(raw).match(/^r(\d+)$/i);if(legacy){const index=Number(legacy[1])-1;if(index>=0&&index<recipes.length)return recipes[index]}return null}
function recipeLabel(raw){if(!raw)return '—';const found=recipeForMeal(raw);return found?found.name:`غذای ذخیره‌شده (${String(raw).replace(/^r/i,'شماره ')})`;}
function mealHealthBadges(r){if(!r)return '';const text=normalizedIngredient(`${r.name} ${(r.ingredients||[]).map(i=>i[0]).join(' ')} ${(r.tags||[]).join(' ')} ${(r.diets||[]).join(' ')}`);const badges=[];if((r.diets||[]).some(x=>/vegan|vegetarian|گیاه/i.test(String(x)))||/عدسی|خوراک لوبیا|دال عدس|سالاد شیرازی|سالاد سبز|سبزیجات بخارپز/.test(text))badges.push(['🌿','گیاه‌خواری']);if(/مرغ|گوشت|ماهی|تخم.?مرغ|عدس|لوبیا|نخود|ماست|پنیر/.test(text))badges.push(['💪','پروتئین‌دار']);if((r.tags||[]).includes('low-salt')||/کم.?نمک/.test(text))badges.push(['🩺','کم‌نمک']);if((r.tags||[]).includes('family')||/زرشک پلو|قورمه سبزی|عدسی|آش|سوپ|ته.?چین|ماکارونی|کتلت/.test(text))badges.push(['🟢','مناسب خانواده']);return badges.slice(0,3).map(([i,t])=>`<span class="week-badge">${i} ${t}</span>`).join('')}
function inventoryMatchForRecipe(r){if(!r)return {percent:0,missing:[],total:0};const names=(state.inventory||[]).map(i=>i.name);const ingredients=(r.ingredients||[]).filter(i=>!/(آب|نمک|فلفل|ادویه|به مقدار لازم|برای سرو)/.test(String(i[0])));if(!ingredients.length)return {percent:100,missing:[],total:0};const missing=ingredients.filter(i=>!inventoryHas(i[0],names));return {percent:Math.round((ingredients.length-missing.length)/ingredients.length*100),missing,total:ingredients.length}}
function roughMealNutrition(r,raw){if(!r)return {kcal:raw&&String(raw).startsWith('snack:')?120:0,protein:raw&&String(raw).startsWith('snack:')?3:0,veg:0};const text=normalizedIngredient(`${r.name} ${(r.ingredients||[]).map(i=>i[0]).join(' ')}`);let kcal=r.category==='صبحانه'?330:r.category==='میان‌وعده'?160:/سالاد|سوپ|آش/.test(text)?280:560;let protein=/مرغ|گوشت|ماهی|تخم.?مرغ|عدس|لوبیا|نخود|ماست|پنیر/.test(text)?25:10;let veg=/سبزی|سالاد|گوجه|خیار|کرفس|کدو|اسفناج|کلم|هویج/.test(text)?1:0;return {kcal,protein,veg}}
function dailyNutrition(values){let kcal=0,protein=0,veg=0,count=0;Object.entries(values||{}).forEach(([meal,raw])=>{if(!raw)return;const r=recipeForMeal(raw),n=roughMealNutrition(r,raw);kcal+=n.kcal;protein+=n.protein;veg+=n.veg;count++});return {kcal,protein,veg,count}}
function complementaryHint(values){const rs=Object.values(values||{}).map(recipeForMeal).filter(Boolean);const text=rs.map(r=>r.name+' '+(r.ingredients||[]).map(i=>i[0]).join(' ')).join(' ');if(/ماهی|لبنیات|ماست|دوغ/.test(text))return 'پیشنهاد جانبی اختیاری: در صورت سازگاری با ذائقه، زعفران برای برنج یا دمنوش هل و دارچین پس از غذا؛ این پیشنهاد سنتی است و ادعای درمانی ندارد.';if(/عدسی|خورش|برنج|چلو|پلو/.test(text))return 'چاشنی پیشنهادی: لیموترش یا سبزی تازه کنار غذا؛ مقدار نمک و چاشنی را با نیاز اعضای خانواده تنظیم کنید.';return ''}
function renderWeek(){const inputDate=isoFromJalali($('#weekStart')?.value);if(inputDate)state.weekStart=inputDate;state.weekStart=state.weekStart||isoToday();const html=DAYS.map((day,i)=>{const key=dayKey(i),values=state.weekly[key]||{},nutrition=dailyNutrition(values),complement=complementaryHint(values);const mealRows=MEALS.map(meal=>{const raw=values[meal],r=recipeForMeal(raw),snack=String(raw||'').startsWith('snack:')?String(raw).slice(6):'',match=inventoryMatchForRecipe(r);let matchHTML='';if(r){const color=match.percent===100?'match-green':match.percent>=75?'match-yellow':'match-red';matchHTML=`<span class="week-match ${color}">${match.percent===100?'🟢 همه مواد موجود':`🔴 تطابق ${fa(match.percent)}٪ · ${fa(match.missing.length)} کسری`}</span>`}return `<div class="meal-row"><label>${meal}</label><div class="week-meal-content"><button class="meal-pick ${(r||snack)?'filled':''}" data-pick-meal="${key}" data-meal="${meal}">${r?`${r.emoji} ${escapeHtml(r.name)}`:snack?`🍎 ${escapeHtml(snack)}`:'＋ انتخاب غذا'}</button>${r?`<div class="week-badges">${mealHealthBadges(r)}${matchHTML}</div>${match.missing.length?`<button class="week-missing-btn" data-week-missing="${r.id}">افزودن مواد کسری به خرید</button>`:''}`:''}</div></div>`}).join('');return `<article class="day-card"><div class="day-head"><span>${day}</span><small>${new Date(key+'T12:00:00').toLocaleDateString('fa-IR',{day:'numeric',month:'short'})}</small></div>${mealRows}<div class="week-day-summary"><b>خلاصه تقریبی روز</b><div><span>🔥 ${fa(nutrition.kcal)} کیلوکالری</span><span>💪 پروتئین: ${fa(nutrition.protein)} گرم</span><span>🥬 وعده‌های دارای سبزی: ${fa(nutrition.veg)}</span></div><small>برآورد ساده بر اساس نوع غذا، نه محاسبه دقیق مواد مغذی؛ برای رژیم درمانی کافی نیست.</small>${complement?`<p class="week-complement">🌼 ${escapeHtml(complement)}</p>`:''}</div></article>`}).join('');$('#weekPlanner').innerHTML=html;$('#weekPlanner').onclick=e=>{const miss=e.target.closest('[data-week-missing]');if(miss){addMissingIngredients(miss.dataset.weekMissing);return}const b=e.target.closest('[data-pick-meal]');if(!b)return;const date=b.dataset.pickMeal,meal=b.dataset.meal;const choices=meal==='صبحانه'?recipes.filter(r=>r.category==='صبحانه'):meal.includes('میان')?recipes.filter(r=>['میان‌وعده','نوشیدنی','دسر'].includes(r.category)):recipes.filter(r=>['غذای اصلی','سالاد و پیش‌غذا'].includes(r.category));const choice=prompt(`غذاهای مناسب ${meal} — شماره را وارد کنید:\n${choices.map((r,i)=>`${i+1}. ${r.name}`).join('\n')}\n\nبرای حذف، 0 وارد کنید.`);if(choice===null)return;const n=Number(choice);if(!Number.isInteger(n)||n<0||n>choices.length){notify('شماره واردشده معتبر نیست.');return}const picked=n===0?null:choices[n-1];if(picked&&(meal==='ناهار'||meal==='شام')){const otherMeal=meal==='ناهار'?'شام':'ناهار';const other=recipeForMeal(state.weekly[date]?.[otherMeal]);const rice=r=>!!r&&(/برنج|پلو|چلو|دمی گوجه/.test(r.name||'')||((r.ingredients||[]).some(x=>/برنج/.test(String(x[0]||'')))&&/کباب|مرغ|ماهی|خورش/.test(r.name||'')));const heavy=r=>!!r&&(/کباب|ماهیچه|سرخ|سوخاری|ته.?چین|فسنجان|قیمه|قورمه|چلو|پلو|لازانیا|پیتزا|برگر/.test(r.name||''));if(other&&rice(picked)&&rice(other)){if(!confirm(`توجه: ${meal} و ${otherMeal} هر دو برنجی می‌شوند. برای تنوع غذایی بهتر است یکی را عوض کنید. با این انتخاب ادامه می‌دهید؟`))return}else if(other&&(heavy(picked)&&heavy(other))){if(!confirm(`توجه: هر دو وعده ${meal} و ${otherMeal} سنگین به نظر می‌رسند. بهتر است یکی از آن‌ها سبک‌تر باشد. با این انتخاب ادامه می‌دهید؟`))return}}if(!state.weekly[date])state.weekly[date]={};state.weekly[date][meal]=picked?picked.id:'';saveState();renderWeek();renderDashboard()}}
function weeklyMissingToShopping(){const used=new Set(),added=[];Object.values(state.weekly||{}).forEach(day=>Object.values(day||{}).forEach(raw=>{const r=recipeForMeal(raw);if(!r)return;const match=inventoryMatchForRecipe(r);match.missing.forEach(i=>{const key=normalizedIngredient(i[0]);if(used.has(key))return;used.add(key);const exists=state.shopping.some(x=>normalizedIngredient(x.name)===key&&!x.done);if(!exists){state.shopping.push({id:uid(),name:i[0],qty:`${i[1]} ${i[2]}`,category:guessShopCategory(i[0]),price:0,done:false,source:'weekly',recipeName:r.name,createdAt:isoToday()});added.push(i[0])}})}));if(!added.length){notify('ماده کسری جدیدی پیدا نشد؛ موجودی و برنامه هفتگی را بررسی کنید.');return}saveState();renderShopping();notify(`${fa(added.length)} قلم کسری به فهرست خرید اضافه شد.`);showView('shopping')}
function weeklyPlanText(){const start=isoToJalaliInput(state.weekStart)||state.weekStart;let lines=[`🍽️ برنامه غذایی هفتگی غذایار`,`هفته از ${start}`,''];DAYS.forEach((day,i)=>{const values=state.weekly[dayKey(i)]||{};const items=MEALS.filter(m=>values[m]).map(m=>{const raw=values[m],r=recipeForMeal(raw);return `${m}: ${r?.name||(String(raw).startsWith('snack:')?String(raw).slice(6):'')}`});lines.push(`${day}:`,...(items.length?items.map(x=>'• '+x):['• هنوز برنامه‌ای ثبت نشده']), '')});return lines.join('\n')}
async function shareWeeklyPlan(){const text=weeklyPlanText();try{if(navigator.share){await navigator.share({title:'برنامه غذایی هفتگی غذایار',text});notify('پنجره اشتراک‌گذاری برنامه باز شد.')}else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);notify('متن برنامه کپی شد؛ آن را در واتساپ، بله، تلگرام یا ایتا ارسال کنید.')}else{prompt('متن برنامه را کپی کنید:',text)}}catch(e){if(e?.name!=='AbortError')prompt('متن برنامه را کپی کنید:',text)}}
function copyWeekToNext(){const oldStart=state.weekStart||isoToday(),oldMeals=JSON.parse(JSON.stringify(state.weekly||{}));if(Object.keys(oldMeals).some(k=>Object.values(oldMeals[k]||{}).some(Boolean)))state.weekArchives.unshift({id:uid(),weekStart:oldStart,savedAt:new Date().toISOString(),meals:oldMeals});const shift=(date,days)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)};const next={};Object.entries(oldMeals).forEach(([date,meals])=>{next[shift(date,7)]=JSON.parse(JSON.stringify(meals))});state.weekly=next;state.weekStart=shift(oldStart,7);$('#weekStart').value=isoToJalaliInput(state.weekStart);saveState();renderWeek();renderDashboard();notify('برنامه این هفته به هفته بعد کپی شد؛ نسخه قبلی هم در آرشیو گزارش‌ها نگهداری شد.')}

function clearWeeklyPlan(){if(!confirm('برنامه غذایی این هفته پاک شود؟ برنامه‌های ذخیره‌شده و آرشیو حذف نمی‌شوند.'))return;state.weekly={};saveState();renderWeek();renderDashboard();notify('برنامه غذایی این هفته پاک شد؛ آرشیوهای ذخیره‌شده حفظ شدند.');}
function saveWeek(){const archive={id:editingWeekArchiveId||uid(),weekStart:state.weekStart,savedAt:new Date().toISOString(),meals:JSON.parse(JSON.stringify(state.weekly))};const idx=state.weekArchives.findIndex(x=>x.id===archive.id);if(idx>=0)state.weekArchives[idx]=archive;else state.weekArchives.unshift(archive);const savedIdx=state.savedPlans.findIndex(x=>x.id===archive.id);if(savedIdx>=0)state.savedPlans[savedIdx]={id:archive.id,weekStart:archive.weekStart,savedAt:archive.savedAt,meals:archive.meals};else state.savedPlans.unshift({id:archive.id,weekStart:archive.weekStart,savedAt:archive.savedAt,meals:archive.meals});editingWeekArchiveId=null;saveState();renderDashboard();renderReports();renderActivityHistory();notify(idx>=0?'تغییرات برنامه آرشیوشده به‌روزرسانی شد.':'برنامه هفتگی ذخیره شد و در تاریخچه قابل بازیابی است.')}
function autoWeek(){
 const profile=$('#weekProfile').value;
 const members=profile==='all'?state.family:state.family.filter(m=>m.id===profile);
 if(profile!=='all'&&!members.length){notify('پروفایل انتخاب‌شده پیدا نشد؛ اعضای خانواده را دوباره بررسی کنید.');return}
 const allowed=recipes.filter(r=>fitsProfile(r,profile));
 if(!allowed.length){notify('برای این پروفایل غذای مناسبِ قابل تشخیص در کتابخانه پیدا نشد. برنامه قبلی حفظ شد.');return}
 const ranked=pool=>pool.map(r=>({r,score:profileRecipeScore(r,members)})).sort((a,b)=>b.score-a.score).map(x=>x.r);
 const breakfast=ranked(allowed.filter(r=>r.category==='صبحانه'));
 const snacks=ranked(allowed.filter(r=>['میان‌وعده','نوشیدنی'].includes(r.category)));
 const mains=ranked(allowed.filter(r=>r.category==='غذای اصلی'));
 const lightMeals=ranked(allowed.filter(r=>['سالاد و پیش‌غذا','میان‌وعده'].includes(r.category)||/سوپ|آش|خوراک سبزیجات|سبزیجات بخارپز|ماست و خیار|سالاد/.test(r.name||'')));
 const isRiceMeal=r=>!!r&&(/برنج|پلو|چلو|دمی گوجه/.test(r.name||'')||((r.ingredients||[]).some(x=>/برنج/.test(String(x[0]||'')))&&/کباب|مرغ|ماهی|خورش/.test(r.name||'')));
 const isHeavyMeal=r=>!!r&&(/کباب|ماهیچه|سرخ|سوخاری|ته.?چین|فسنجان|قیمه|قورمه|چلو|پلو|لازانیا|پیتزا|برگر/.test(r.name||''));
 if(breakfast.length<7||mains.length<14){notify('تنوع کتابخانه برای ساخت برنامه هفتگی بدون تکرار کافی نیست؛ برنامه قبلی حفظ شد.');return}
 const used=new Set();
 const chooseUnique=(pool)=>{const r=pool.find(x=>!used.has(x.id));if(r)used.add(r.id);return r||null};
 const chooseReplacement=(pool,exclude)=>pool.find(r=>!used.has(r.id)&&!exclude.includes(r.id))||null;
 const next={};
 for(let i=0;i<7;i++){
  const key=dayKey(i);next[key]={};
  next[key]['صبحانه']=(chooseUnique(breakfast)||{}).id||'';
  for(const meal of ['میان‌وعده اول','میان‌وعده دوم'])next[key][meal]=(chooseUnique(snacks)||{}).id||'';
  next[key]['ناهار']=(chooseUnique(mains)||{}).id||'';
  next[key]['شام']=(chooseUnique(mains)||{}).id||'';
  let lunch=recipes.find(r=>r.id===next[key]['ناهار']),dinner=recipes.find(r=>r.id===next[key]['شام']);
  if(lunch&&dinner&&isRiceMeal(lunch)&&isRiceMeal(dinner)){
   const repl=chooseReplacement(mains.filter(r=>!isRiceMeal(r)),[lunch.id,dinner.id]);
   if(repl){used.delete(dinner.id);next[key]['شام']=repl.id;used.add(repl.id);dinner=repl;}
  }
  lunch=recipes.find(r=>r.id===next[key]['ناهار']);dinner=recipes.find(r=>r.id===next[key]['شام']);
  if(lunch&&dinner&&(isHeavyMeal(lunch)||isHeavyMeal(dinner))){
   const repl=chooseReplacement(lightMeals.filter(r=>!isHeavyMeal(r)&&!isRiceMeal(r)),[lunch.id,dinner.id]);
   if(repl){used.delete(dinner.id);next[key]['شام']=repl.id;used.add(repl.id);}
  }
 }
 state.weekly=next;state.weekStart=state.weekStart||isoToday();$('#weekStart').value=isoToJalaliInput(state.weekStart);saveState();renderWeek();renderDashboard();
 const filled=Object.values(next).flatMap(day=>Object.values(day)).filter(Boolean).length;
 notify(`برنامه هفتگی ساخته شد: ${fa(filled)} وعده بدون تکرار در حد تنوع کتابخانه. غذاهای برنجی و سنگین نیز تا حد امکان متعادل شده‌اند.`);
}
function updateProfileOptions(){const sel=$('#weekProfile');if(!sel)return;const val=sel.value;sel.innerHTML='<option value="all">همه اعضای خانواده</option>'+state.family.map(m=>`<option value="${m.id}">${escapeHtml(m.name)}</option>`).join('');if([...sel.options].some(o=>o.value===val))sel.value=val}
function profileRecipeScore(r,members){
 const text=normalizedIngredient(`${r.name||''} ${r.description||''} ${(r.ingredients||[]).map(i=>i[0]).join(' ')} ${(r.tags||[]).join(' ')} ${(r.diets||[]).join(' ')}`);
 const tags=Array.isArray(r.tags)?r.tags:[];let score=0;
 for(const m of members){
  if(m.health==='دیابت'){if(/سالاد|سبزی|حبوبات|عدس|لوبیا|مرغ|ماهی|تخم.?مرغ|بدون قند|بدون شکر/.test(text))score+=4;if(/شیرینی|کیک|بستنی|شربت|نوشابه|آب.?میوه|حلوا|قند|شکر|عسل|شکلات|تیرامیسو|چیز.?کیک/.test(text))score-=20;}
  if(m.health==='فشار خون بالا'){if(tags.includes('low-salt')||/کم.?نمک/.test(text))score+=10;if(/سبزی|سالاد|بخارپز|میوه|حبوبات/.test(text))score+=3;if(/خیارشور|شور|سوسیس|کالباس|کنسرو|چیپس|نمک زیاد/.test(text))score-=12;}
  if(m.health==='بیماری قلبی'){if(tags.includes('heart')||/کم.?چرب|کم.?روغن/.test(text))score+=8;if(/ماهی|سبزی|سالاد|حبوبات|بخارپز/.test(text))score+=3;if(/سرخ.?کرده|پرچرب|خامه|کره فراوان|سوسیس|کالباس/.test(text))score-=10;}
  if(m.activity==='ورزشکار'||m.goal==='gain'){if(tags.includes('high-protein')||tags.includes('sport'))score+=8;if(/مرغ|گوشت|ماهی|تخم.?مرغ|عدس|لوبیا|نخود|ماست|پنیر|مغز|پروتئین/.test(text))score+=5;}
  if(m.goal==='loss'&&/سالاد|سوپ|سبزی|بخارپز|کم.?روغن/.test(text))score+=4;
  if(m.goal==='plant'&&(/گیاهی|سبزی|عدس|لوبیا|نخود|سالاد|میوه/.test(text)||tags.includes('vegan')))score+=4;
  const likes=(m.likes||[]).map(normalizedIngredient).filter(Boolean);if(likes.some(x=>text.includes(x)))score+=5;
  if(m.favoriteMeal==='صبحانه مفصل'&&r.category==='صبحانه')score+=2;
  if(m.temperament&&m.temperament!=='unspecified'&&m.temperament.startsWith('سرد')&&/زعفران|دارچین|زنجبیل|هل/.test(text))score+=1;
 }
 return score;
}
function fitsProfile(r,profile){const members=profile==='all'?state.family:state.family.filter(x=>x.id===profile);return members.every(m=>fitsMember(r,m))}
function fitsMember(r,m){
 const diets=Array.isArray(r.diets)?r.diets:[],tags=Array.isArray(r.tags)?r.tags:[],ingredients=Array.isArray(r.ingredients)?r.ingredients:[];
 const text=normalizedIngredient(`${r.name||''} ${r.description||''} ${ingredients.map(i=>i[0]).join(' ')} ${tags.join(' ')} ${diets.join(' ')}`);
 const name=normalizedIngredient(r.name||'');
 if(m.diet==='vegetarian'&&!(diets.includes('vegetarian')||diets.includes('vegan')||tags.includes('vegetarian')||tags.includes('vegan')||/عدسی|دال عدس|خوراک لوبیا|فلافل|سالاد شیرازی|سالاد سبز|سبزیجات بخارپز|املت سبزیجات/.test(text)))return false;
 if(m.diet==='vegan'&&!(diets.includes('vegan')||tags.includes('vegan')||/عدسی|دال عدس|خوراک لوبیا|فلافل|سالاد شیرازی|سالاد سبز|سبزیجات بخارپز/.test(text)))return false;
 if(m.diet==='raw'&&!diets.includes('raw')&&!tags.includes('raw'))return false;
 if(m.diet==='low-salt'&&/خیارشور|شور|سوسیس|کالباس|کنسرو|چیپس|نمک زیاد/.test(text))return false;
 const sugary=/شیرینی|کیک|بستنی|شربت|نوشابه|آب.?میوه|حلوا|قند|شکر|عسل|شکلات|تیرامیسو|چیز.?کیک|دسر شیرین/;
 if(m.health==='دیابت'&&(sugary.test(text)||r.category==='دسر'||r.category==='نوشیدنی'&&!/بدون قند|بدون شکر|بدون شیرین.?کننده/.test(text)))return false;
 if(m.health==='فشار خون بالا'&&/خیارشور|شور|سوسیس|کالباس|کنسرو|چیپس|نمک زیاد/.test(text))return false;
 if(m.health==='بیماری قلبی'&&/سرخ.?کرده|پرچرب|خامه|کره فراوان|سوسیس|کالباس/.test(text))return false;
 if(m.activity==='ورزشکار'||m.goal==='gain'){if(['غذای اصلی','صبحانه','میان‌وعده'].includes(r.category)&&!/مرغ|گوشت|ماهی|تخم.?مرغ|عدس|لوبیا|نخود|ماست|پنیر|مغز|پروتئین|sport|high-protein/.test(text)&&!tags.includes('sport')&&!tags.includes('high-protein'))return false;}
 const avoid=(m.avoid||[]).map(normalizedIngredient).filter(Boolean);if(avoid.some(a=>text.includes(a)||ingredients.some(i=>{const ingredient=normalizedIngredient(i[0]);return ingredient&&(ingredient.includes(a)||a.includes(ingredient))})))return false;
 return true;
}
function renderRecipes(){const grid=$('#recipeGrid');if(!grid)return;grid.innerHTML='<div class="empty-state">در حال بارگذاری غذاها…</div>';try{const q=String($('#recipeSearch')?.value||'').trim().toLowerCase(),cat=$('#recipeCategory')?.value||'all',diet=$('#dietFilter')?.value||'all',time=$('#timeFilter')?.value||'all';const source=Array.isArray(recipes)?recipes:[];let list=source.filter(r=>{r=r||{};const ingredients=Array.isArray(r.ingredients)?r.ingredients:[];const searchable=[r.name||'',r.description||'',...ingredients.map(i=>Array.isArray(i)?i[0]:'')].join(' ').toLowerCase();return(!q||searchable.includes(q))&&(cat==='all'||(r.category||'')===cat)&&(time==='all'||(time==='quick'?Number(r.time||0)<30:Number(r.time||0)>=30&&Number(r.time||0)<=60))});if(diet!=='all')list=list.filter(r=>{const diets=Array.isArray(r.diets)?r.diets:[],tags=Array.isArray(r.tags)?r.tags:[];if(diet==='vegetarian')return diets.includes('vegetarian');if(diet==='vegan')return diets.includes('vegan');if(diet==='raw')return diets.includes('raw');if(diet==='diabetes')return tags.includes('diabetes')||['سالاد و پیش‌غذا','میان‌وعده'].includes(r.category);if(diet==='pressure')return tags.includes('low-salt')||['سالاد و پیش‌غذا','میان‌وعده'].includes(r.category);if(diet==='heart')return tags.includes('heart')||['سالاد و پیش‌غذا','میان‌وعده'].includes(r.category);if(diet==='sport')return tags.includes('sport')||diets.includes('vegetarian');if(diet==='organic')return !!r.organic;return true});if(!list.length){grid.innerHTML='<div class="empty-state">غذایی با این فیلترها پیدا نشد. فیلترها را روی «همه» بگذارید.</div>';return}const cards=[];for(const recipe of list){try{cards.push(recipeCard(recipe))}catch(cardError){console.error('Recipe card error:',cardError)}}grid.innerHTML=cards.length?cards.join(''):'<div class="empty-state">غذاها بارگذاری نشدند. لطفاً صفحه را دوباره باز کنید.</div>'}catch(error){console.error('Recipe list error:',error);grid.innerHTML='<div class="empty-state">در نمایش فهرست غذاها خطا رخ داد. لطفاً صفحه را دوباره باز کنید.</div>'}}
function recipeCard(r){const diets=Array.isArray(r.diets)?r.diets:[];const saved=Array.isArray(state.savedRecipes)?state.savedRecipes:[];return `<article class="recipe-card"><div class="recipe-card-top"><span class="badge">${escapeHtml(r.category||'غذا')}</span>${r.emoji||'🍲'}</div><div class="recipe-card-body"><h3>${escapeHtml(r.name||'غذای بدون نام')}</h3><p>${escapeHtml(r.description||'')}</p><div class="recipe-meta"><span>◷ ${fa(r.time||0)} دقیقه</span><span>♧ ${diets.includes('vegan')?'وگان':diets.includes('vegetarian')?'گیاهی':'معمولی'}</span></div><div class="card-actions"><button data-recipe-details="${r.id||''}">طرز تهیه</button><button data-recipe-save="${r.id||''}">${saved.includes(r.id)?'★ ذخیره‌شده':'☆ ذخیره'}</button></div></div></article>`}
function recipeGridAction(e){const d=e.target.closest('[data-recipe-details]'),s=e.target.closest('[data-recipe-save]');if(d)openRecipe(d.dataset.recipeDetails);if(s){const id=s.dataset.recipeSave;state.savedRecipes=state.savedRecipes.includes(id)?state.savedRecipes.filter(x=>x!==id):[...state.savedRecipes,id];saveState();renderRecipes();notify('وضعیت ذخیره دستور پخت تغییر کرد.')}}
function openRecipe(id){const r=recipes.find(x=>x.id===id);if(!r)return;activeRecipe=r;$('#recipeDialogContent').innerHTML=`<span class="eyebrow">${escapeHtml(r.category)} · ${fa(r.time)} دقیقه</span><h2>${r.emoji} ${escapeHtml(r.name)}</h2><p>${escapeHtml(r.description)}</p><h3>مواد لازم</h3>${r.ingredients.length?`<ul>${r.ingredients.map(i=>`<li>${escapeHtml(i[0])} — ${escapeHtml(i[1])} ${escapeHtml(i[2])}</li>`).join('')}</ul>`:'<p class="muted">مواد اولیه هنوز ثبت نشده است.</p>'}<h3>طرز تهیه</h3>${r.steps.length?`<ol>${r.steps.map(s=>`<li>${escapeHtml(s)}</li>`).join('')}</ol>`:'<p class="muted">مراحل اختصاصی تهیه هنوز ثبت نشده است.</p>'}<div class="menu-actions"><button class="primary-btn" id="recipePdfBtn">چاپ / ذخیره PDF</button><button class="secondary-btn" id="recipeToShopping" ${r.ingredients.length?'':'disabled'}>افزودن مواد به فهرست خرید</button><button class="secondary-btn" id="saveRecipeFromDialog">${state.savedRecipes.includes(r.id)?'حذف از ذخیره‌ها':'ذخیره دستور'}</button></div>`;$('#recipeDialogContent').onclick=e=>{if(e.target.id==='recipePdfBtn'){const body=`<div class="recipe-report-meta"><p><b>دسته‌بندی:</b> ${escapeHtml(r.category)} &nbsp; | &nbsp; <b>زمان آماده‌سازی:</b> ${fa(r.time)} دقیقه</p><p>${escapeHtml(r.description||'')}</p></div><h3>مواد لازم</h3>${r.ingredients.length?`<table><thead><tr><th>ماده اولیه</th><th>مقدار</th><th>واحد</th></tr></thead><tbody>${r.ingredients.map(i=>`<tr><td>${escapeHtml(i[0])}</td><td>${escapeHtml(i[1])}</td><td>${escapeHtml(i[2])}</td></tr>`).join('')}</tbody></table>`:'<p>مواد اولیه ثبت نشده است.</p>'}<h3>طرز تهیه</h3>${r.steps.length?`<ol class="recipe-steps">${r.steps.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ol>`:'<p>مراحل اختصاصی ثبت نشده است.</p>'}`;printHtmlDocument('دستور پخت: '+r.name,body)}if(e.target.id==='recipeToShopping'){addRecipeIngredientsToShopping(r);$('#recipeDialog').close()}if(e.target.id==='saveRecipeFromDialog'){state.savedRecipes=state.savedRecipes.includes(r.id)?state.savedRecipes.filter(x=>x!==r.id):[...state.savedRecipes,r.id];saveState();openRecipe(r.id);renderRecipes();notify('دستور پخت ذخیره شد.')}};if($('#recipeDialog').showModal)$('#recipeDialog').showModal();else alert(`${r.name}\n${r.steps.join('\n')}`)}
function renderPartyRecipes(){if(!$('#partyRecipeResults'))return;const q=$('#partySearch').value.trim().toLowerCase(),cat=$('#partyCategory').value;const list=recipes.filter(r=>(!q||r.name.toLowerCase().includes(q))&&(cat==='all'||r.category===cat));$('#partyRecipeResults').innerHTML=list.map(r=>`<div class="mini-recipe"><span class="food-emoji">${r.emoji}</span><div><b>${escapeHtml(r.name)}</b><small>${fa(r.time)} دقیقه · ${escapeHtml(r.category)}</small></div><button data-add-party="${r.id}">افزودن</button></div>`).join('')}
function readPartyMeta(){return {id:state.partyMeta?.id||uid(),name:$('#partyName').value.trim(),guests:Math.max(1,Number($('#guestCount').value)||1),date:isoFromJalali($('#partyDate').value)||state.partyMeta?.date||isoToday(),meal:$('#partyMeal').value,type:$('#partyType').value,style:$('#partyStyle').value,budget:$('#partyBudget').value?Number($('#partyBudget').value):null,notes:$('#partyNotes').value.trim()}}
function addPartyRecipe(id){if(!state.partyMenu.includes(id))state.partyMenu.push(id);saveState();renderPartyMenu();notify('غذا به منوی مهمانی اضافه شد.')}
function renderPartySuggestions(){
 const el=$('#partySuggestedMenu');if(!el)return;
 const p=state.partyMeta||readPartyMeta();
 const note=String(p.notes||'');
 const count=Math.max(1,Number(p.guests)||1);
 const norm=s=>String(s||'').toLowerCase().replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/‌/g,' ');
 const categories=p.meal==='صبحانه'
  ? [['صبحانه','🥣'],['میان‌وعده','🍎'],['نوشیدنی','🥤'],['دسر','🍮']]
  : p.meal==='میان‌وعده'
   ? [['میان‌وعده','🍎'],['نوشیدنی','🥤'],['دسر','🍮']]
   : [['غذای اصلی','🍽️'],['سالاد و پیش‌غذا','🥗'],['دسر','🍮'],['نوشیدنی','🥤']];
 const isFast=/فست.?فودی|فست فود/.test(p.style||'');
 const isLuxury=/مجلل|رسمی/.test((p.style||'')+' '+(p.type||''));
 const isTraditional=/سنتی|خانوادگی|خودمانی|مراسم عزا/.test((p.style||'')+' '+(p.type||''));
 const isCelebration=/جشن|مجلل/.test((p.type||'')+' '+(p.style||''));
 const has=(r,re)=>re.test(norm(r.name)+' '+norm((r.ingredients||[]).map(i=>i[0]).join(' ')));
 const dietaryReason=r=>{
  const n=norm(r.name),ing=norm((r.ingredients||[]).map(i=>i[0]).join(' ')),all=n+' '+ing;
  if(/وگان/.test(note)&&/(گوشت|مرغ|ماهی|میگو|تخم مرغ|شیر|ماست|پنیر|کشک|خامه|کره|عسل|ژامبون|سوسیس|کالباس|بستنی|تخم مرغ)/.test(all))return true;
  if(/گیاه.?خواری|گیاهی/.test(note)&&/(گوشت|مرغ|ماهی|میگو|ژامبون|سوسیس|کالباس|بوقلمون|ماهیچه)/.test(all))return true;
  if(/مغزها/.test(note)&&/(گردو|بادام|فندق|پسته|بادام زمینی|مغزها|مغزیجات)/.test(all))return true;
  if(/لبنیات/.test(note)&&/(شیر|ماست|پنیر|کشک|خامه|کره|بستنی|دوغ|پنیر پیتزا)/.test(all))return true;
  if(/تخم.?مرغ/.test(note)&&/(تخم مرغ|مایونز|سس مایونز)/.test(all))return true;
  if(/گلوتن/.test(note)&&/(نان|آرد|ماکارونی|پاستا|رشته|بلغور|جوپرک|سوخاری|تارت|کیک|باقلوا|وافل)/.test(all))return true;
  if(/گوشت قرمز/.test(note)&&/(گوشت قرمز|گوشت خورشتی|گوشت چرخ کرده|ماهیچه|کباب کوبیده|قیمه|قورمه|فسنجان با گوشت)/.test(all))return true;
  if(/دیابت|کنترل قند/.test(note)&&/(شکر|قند|عسل|شربت|بستنی|حلوا|شله زرد|زولبیا|بامیه|نوشابه|کوکاکولا|شیرین پلو|آلبالو پلو|ژله|کیک|شیرینی|باقلوا)/.test(all))return true;
  if(/کم.?نمک|فشار خون/.test(note)&&/(خیارشور|سوسیس|کالباس|ژامبون|چیپس|نوشابه|نمک زیاد)/.test(all))return true;
  if(/بدون تندی|تندی/.test(note)&&/(فلافل جنوبی تند|فلفل تند|چیلی|سس تند|موهیتو تند)/.test(all))return true;
  return false;
 };
 const score=r=>{
  let n=norm(r.name),s=0;
  if(isFast){if(/پیتزا|برگر|فلافل|لازانیا|پاستا|ساندویچ|هات.?داگ|ناگت|سیب.?زمینی|سمبوسه|فینگرفود/.test(n))s+=12;else if(/کباب|خورش|پلو|ته.?چین|ماهیچه/.test(n))s-=4;}
  if(isLuxury){if(/زعفران|کباب|ته.?چین|مرصع|زرشک پلو|باقالی پلو|فسنجان|ماهی|تارت|تیرامیسو|چیزکیک|بستنی سنتی|شربت زعفران|گلاب/.test(n))s+=9;if(/عدسی|استانبولی|سیب.?زمینی سرخ/.test(n))s-=2;}
  if(isTraditional){if(/قورمه|قیمه|کباب|پلو|دیزی|آبگوشت|کشک بادمجان|میرزا قاسمی|سوپ|شله.?زرد|حلوا|دوغ|چای/.test(n))s+=5;}
  if(isCelebration&&/جشن/.test(p.type||'')){if(/زرشک پلو|ته.?چین|مرصع|کباب|فسنجان|تارت|ژله|بستنی|شربت|آبمیوه|سالاد/.test(n))s+=4;}
  if(p.meal==='صبحانه'){if(/صبحانه|نان و پنیر|عدسی|تخم.?مرغ|پنکیک|چای|قهوه|شیر/.test(n))s+=7;else if(r.category==='غذای اصلی')s-=5;}
  if(p.meal==='میان‌وعده'){if(['نوشیدنی','دسر','میان‌وعده','سالاد و پیش‌غذا'].includes(r.category))s+=6;else s-=4;}
  if(p.meal==='ناهار'&&r.category==='غذای اصلی')s+=3;
  if(p.meal==='شام'&&(/سوپ|سالاد|مرغ|ماهی|پاستا|کباب/.test(n)))s+=2;
  if(/مراسم عزا/.test(p.type||'')&&/حلوا|خرما|چای|شله.?زرد|سوپ|خورش|پلو/.test(n))s+=5;
  if(/ساده|حاضری/.test(p.style||'')&&/سالاد|ساندویچ|سیب.?زمینی|عدسی|املت|سوپ|نوشیدنی/.test(n))s+=5;
  if(/گیاهی/.test(p.style||'')){if(!/(گوشت|مرغ|ماهی|میگو|ژامبون|سوسیس|کالباس|ماهیچه)/.test(n))s+=6;}
  if(/رسمی/.test(p.style||'')&&/کباب|زرشک پلو|ته.?چین|مرصع|فسنجان/.test(n))s+=3;
  return s;
 };
 const limit=Math.min(5,Math.max(3,Math.ceil(count/4)));
 const sections=categories.map(([cat,icon])=>{
  let pool=recipes.filter(r=>r.category===cat&&!dietaryReason(r));
  // Hard category gate: breakfast suggestions must come only from breakfast recipes.
  if(p.meal==='صبحانه'&&cat==='صبحانه') pool=pool.filter(r=>r.category==='صبحانه');
  if(p.meal==='میان‌وعده') pool=pool.filter(r=>['میان‌وعده','نوشیدنی','دسر'].includes(r.category));
  pool.sort((a,b)=>score(b)-score(a)||a.name.localeCompare(b.name,'fa'));
  const selected=pool.slice(0,limit);
  return `<section class="party-suggestion-section"><h4>${icon} ${cat}<small>${fa(selected.length)} پیشنهاد</small></h4>${selected.length?selected.map(r=>`<div class="suggestion-row"><span class="food-emoji">${r.emoji||'🍽️'}</span><div class="party-suggestion-text"><b>${escapeHtml(r.name)}</b><small>${escapeHtml(cat)} · ${fa(count)} مهمان · ${fa(r.time||30)} دقیقه</small></div><button type="button" data-add-party="${r.id}">${state.partyMenu.includes(r.id)?'افزوده شده ✓':'افزودن به منو'}</button></div>`).join(''):`<p class="party-no-match">با محدودیت ثبت‌شده، گزینه‌ای در این دسته پیدا نشد.</p>`}</section>`;
 }).join('');
 const filters=`<div class="party-filter-summary"><b>پیشنهادهای متناسب با مشخصات مهمانی</b><span>${escapeHtml(p.type||'نوع تعیین نشده')} · ${escapeHtml(p.style||'سبک تعیین نشده')} · ${escapeHtml(p.meal||'وعده تعیین نشده')} · ${fa(count)} مهمان</span>${note?`<small>محدودیت اعمال‌شده: ${escapeHtml(note)} — مواد واقعی دستورها را پیش از پذیرایی بررسی کنید.</small>`:''}</div>`;
 el.innerHTML=filters+sections+`<p class="party-diet-disclaimer">فیلترها بر اساس نام غذا و مواد ثبت‌شده عمل می‌کنند و ممکن است همه مواد پنهان یا تماس متقاطع را تشخیص ندهند؛ در حساسیت شدید، برچسب و دستور کامل را بررسی کنید.</p>`;
}
function renderPartyMenu(){const el=$('#partyMenuList');if(!el)return;const list=state.partyMenu.map(id=>recipes.find(r=>r.id===id)).filter(Boolean);el.classList.toggle('empty-state',!list.length);el.innerHTML=list.length?list.map(r=>`<div class="selected-item"><span>${r.emoji} <b>${escapeHtml(r.name)}</b> <small>· ${escapeHtml(r.category)}</small></span><button data-remove-party="${r.id}">حذف</button></div>`).join(''):'هنوز غذایی به منو اضافه نشده است.';if(state.partyMeta)$('#partyMenuSummary').textContent=`${state.partyMeta.name} · ${fa(state.partyMeta.guests)} مهمان · ${isoToJalaliInput(state.partyMeta.date)}`;renderPartyDietWarnings();renderPartyEstimate();renderPartyChecklist();renderPartyTimeline()}
function renderGuests(){if(!$('#guestList'))return;const labels={vegetarian:'گیاه‌خوار',vegan:'وگان',diabetes:'کنترل قند', 'low-salt':'کم‌نمک',dairy:'حساسیت لبنیات',nuts:'حساسیت مغزها',egg:'حساسیت تخم‌مرغ',spicy:'بدون ادویه تند'};$('#guestList').innerHTML=state.partyGuests.length?state.partyGuests.map(g=>`<span class="guest-chip">${escapeHtml(g.name)}${g.diet?` · ${escapeHtml(labels[g.diet]||g.diet)}`:''}${g.note?` · ${escapeHtml(g.note)}`:''}<button data-remove-guest="${g.id}" aria-label="حذف">×</button></span>`).join(''):'<small class="hint">هنوز نامی ثبت نشده است.</small>';renderPartyDietWarnings()}
function partyRecipes(){return state.partyMenu.map(id=>recipes.find(r=>r.id===id)).filter(Boolean)}
function renderPartyDietWarnings(){const el=$('#guestDietWarnings');if(!el)return;const menu=partyRecipes();const warns=[];state.partyGuests.filter(g=>g.diet).forEach(g=>{const bad=menu.filter(r=>{const ing=r.ingredients.map(i=>i[0]).join(' ').toLowerCase();if(g.diet==='vegetarian')return /گوشت|مرغ|ماهی|میگو|ژامبون|سوسیس|کالباس/.test(ing);if(g.diet==='vegan')return /گوشت|مرغ|ماهی|میگو|ژامبون|سوسیس|کالباس|شیر|ماست|پنیر|کشک|خامه|کره|عسل|تخم.?مرغ/.test(ing);if(g.diet==='diabetes')return /شکر|قند|عسل|شربت|بستنی|حلوا|شله.?زرد/.test(r.name+' '+ing);if(g.diet==='low-salt')return /نمک|خیارشور|پنیر شور|سوسیس|کالباس/.test(ing);if(g.diet==='dairy')return /شیر|ماست|پنیر|کشک|خامه|کره|بستنی/.test(ing);if(g.diet==='nuts')return /گردو|بادام|فندق|پسته|بادام.?زمینی|مغز/.test(ing);if(g.diet==='egg')return /تخم.?مرغ|مایونز/.test(ing);if(g.diet==='spicy')return /فلفل تند|چیلی|سس تند/.test(ing);return false});if(bad.length)warns.push(`<li><b>${escapeHtml(g.name)}</b> (${escapeHtml(g.diet)}) — لطفاً این موارد را بررسی کنید: ${bad.map(r=>escapeHtml(r.name)).join('، ')}</li>`)});el.innerHTML=warns.length?`<div class="warning-box"><b>⚠ هشدار بررسی رژیم مهمانان</b><ul>${warns.join('')}</ul><small>این تطبیق بر اساس نام غذا و مواد ثبت‌شده، تقریبی است؛ برچسب‌ها و دستور واقعی را بررسی کنید. در حساسیت شدید، از تماس متقاطع نیز جلوگیری شود.</small></div>`:''}
function renderPartyEstimate(){const el=$('#partyEstimate');if(!el)return;const p=state.partyMeta||readPartyMeta(),count=Math.max(1,Number(p.guests)||1),list=partyRecipes();if(!list.length){el.innerHTML='<p class="muted">برای دیدن برآورد، غذاهایی به منو اضافه کنید.</p>';return}const sums=new Map();list.forEach(r=>r.ingredients.forEach(i=>{const key=i[0],unit=i[2]||'',q=Number(i[1]);if(!sums.has(key))sums.set(key,{name:key,unit,amount:Number.isFinite(q)?q:null,qty:null});else{const old=sums.get(key);if(old.unit===unit&&Number.isFinite(q)&&old.amount!==null)old.amount+=q;else old.amount=null}}));sums.forEach(x=>{x.qty=x.amount!==null?estimateIngredientQty(x.amount,x.unit,count):`${x.name} · مقدار تقریبی`});const shopCost=state.shopping.filter(x=>!x.done&&x.source==='party'&&(!p.name||x.partyName===p.name)).reduce((n,x)=>n+Math.max(0,Number(x.price)||0),0);const priced=state.shopping.filter(x=>!x.done&&x.source==='party'&&Number(x.price)>0&&(!p.name||x.partyName===p.name)).length;el.innerHTML=`<div class="estimate-metrics"><div><small>تعداد مهمان</small><b>${fa(count)} نفر</b></div><div><small>اقلام منحصربه‌فرد</small><b>${fa(sums.size)} قلم</b></div><div><small>جمع قیمت‌های ثبت‌شده</small><b>${priced?fa(shopCost)+' تومان':'هنوز ثبت نشده'}</b></div></div><div class="estimate-ingredients">${[...sums.values()].map(x=>`<div><span>${escapeHtml(x.name)}</span><b>${escapeHtml(String(x.qty))}</b></div>`).join('')}</div><button type="button" class="secondary-btn" id="estimateToShopping">افزودن مواد به فهرست خرید</button>`;$('#estimateToShopping')?.addEventListener('click',partyToShopping)}
const partyChecklistDefaults=[['plates','بشقاب غذاخوری','به تعداد مهمان + ۲'],['cutlery','قاشق و چنگال','هرکدام به تعداد مهمان + ۲'],['glasses','لیوان','به تعداد مهمان + ۲'],['napkins','دستمال سفره','حداقل ۲ عدد برای هر نفر'],['serving','ظروف سرو و دیس‌ها','بر اساس تعداد غذاها'],['tablecloth','رومیزی و سفره','۱ عدد + یدک'],['trash','کیسه زباله و دستمال نظافت','آماده'],['tea','چای و وسایل پذیرایی','بر اساس تعداد مهمان']];
function renderPartyChecklist(){const el=$('#partyChecklist');if(!el)return;const n=Math.max(1,Number($('#guestCount')?.value)||state.partyMeta?.guests||1);el.innerHTML=partyChecklistDefaults.map(([id,name,qty])=>`<label class="party-check-row"><input type="checkbox" data-party-check="${id}" ${state.partyChecklist[id]?'checked':''}><span><b>${name}</b><small>${qty.includes('تعداد مهمان')?`حدود ${fa(n+2)} عدد`:qty.includes('هرکدام')?`حدود ${fa(n+2)} عدد از هرکدام`:qty.includes('هر نفر')?`حدود ${fa(n*2)} عدد`:qty}</small></span></label>`).join('')}
function renderPartyTimeline(){const el=$('#partyTimeline');if(!el)return;const defaults=[{id:'daybefore-dessert',name:'آماده‌سازی دسرهای نیازمند سردشدن',when:'روز قبل',done:false},{id:'daybefore-shop',name:'خرید مواد تازه و بررسی ظروف',when:'روز قبل',done:false},{id:'soak',name:'خیساندن حبوبات (در صورت نیاز)',when:'شب قبل',done:false},{id:'saffron',name:'دم‌کردن زعفران',when:'۱ تا ۲ ساعت قبل از سرو',done:false},{id:'cook',name:'شروع پخت غذاهای زمان‌بر',when:'بر اساس زمان سرو',done:false},{id:'salad',name:'آماده‌سازی سالاد و چاشنی‌ها',when:'نزدیک زمان سرو',done:false},{id:'tea',name:'آماده‌کردن چای و نوشیدنی',when:'نزدیک ورود مهمانان',done:false}];const tasks=[...defaults,...state.partyTasks];el.innerHTML=tasks.map(t=>`<label class="party-check-row ${t.done?'is-done':''}"><input type="checkbox" data-party-task-check="${t.id}" ${t.done?'checked':''}><span><b>${escapeHtml(t.name)}</b><small>${escapeHtml(t.when||'زمان تعیین نشده')}</small></span>${state.partyTasks.some(x=>x.id===t.id)?`<button type="button" data-delete-party-task="${t.id}" aria-label="حذف کار">×</button>`:''}</label>`).join('')}
function partyShareText(){const p=state.partyMeta||readPartyMeta(),list=partyRecipes();return `🌿 ${p.name||'منوی مهمانی'}\nتاریخ: ${isoToJalaliInput(p.date)||p.date}\nتعداد مهمان: ${p.guests}\nوعده: ${p.meal}\n\n🍽️ منو:\n${list.map(r=>'• '+r.name).join('\n')||'هنوز منویی انتخاب نشده'}\n\nساخته‌شده با غذایار`}
function shareParty(){const text=partyShareText();if(navigator.share){navigator.share({title:'منوی مهمانی غذایار',text}).catch(()=>{})}else{const url='https://wa.me/?text='+encodeURIComponent(text);window.open(url,'_blank','noopener');}}
function printPartyPrep(){const p=state.partyMeta||readPartyMeta(),list=partyRecipes(),items=state.shopping.filter(x=>x.source==='party'&&!x.done&&(!p.name||x.partyName===p.name)),tasks=[...state.partyTasks];const w=window.open('','_blank');if(!w){notify('اجازه بازشدن پنجره چاپ را بدهید.');return}w.document.write(`<html lang="fa" dir="rtl"><meta charset="utf-8"><title>تشریفات مهمانی - ${escapeHtml(p.name)}</title><style>body{font-family:Tahoma,sans-serif;padding:25px;line-height:2;color:#243b32}h1,h2{color:#176b55}li{margin:4px 0}.muted{color:#68786e}.check{border:1px solid #ddd;padding:8px;margin:5px 0;border-radius:6px}@page{size:A4;margin:15mm}</style><h1>غذایار | برنامه تشریفات مهمانی</h1><p>${escapeHtml(p.name||'مهمانی')} · ${escapeHtml(isoToJalaliInput(p.date)||p.date)} · ${fa(p.guests)} مهمان</p><h2>منوی انتخابی</h2><ol>${list.map(r=>`<li>${escapeHtml(r.name)} — ${escapeHtml(r.category)}</li>`).join('')}</ol><h2>فهرست خرید مهمانی</h2><ul>${items.map(i=>`<li>${escapeHtml(i.name)} — ${escapeHtml(i.qty||'مقدار تعیین نشده')} ${Number(i.price)>0?'('+fa(i.price)+' تومان)':''}</li>`).join('')||'<li>هنوز مواد به فهرست خرید اضافه نشده است.</li>'}</ul><h2>چک‌لیست ظروف و تدارکات</h2>${partyChecklistDefaults.map(([id,name,qty])=>`<div class="check">□ ${escapeHtml(name)} — ${escapeHtml(qty)} ${state.partyChecklist[id]?'(تأیید شد)':''}</div>`).join('')}<h2>زمان‌بندی</h2><ul>${[...tasks].map(t=>`<li>${escapeHtml(t.when||'زمان نامشخص')}: ${escapeHtml(t.name)} ${t.done?'✓':''}</li>`).join('')}</ul><h2>یادداشت و محدودیت غذایی</h2><p>${escapeHtml(p.notes||'—')}</p><p class="muted">برآورد مقدارها تقریبی است؛ قیمت‌ها فقط در صورت ثبت در فهرست خرید نمایش داده می‌شوند. هشدارهای رژیمی جایگزین بررسی مواد واقعی نیستند.</p><script>window.onload=()=>window.print()<\/script></html>`);w.document.close()}
function saveParty(){const meta=readPartyMeta();if(!meta.name){notify('ابتدا عنوان مهمانی را وارد کنید.');$('#partyName').focus();return}if(!state.partyMenu.length){notify('حداقل یک غذا به منوی مهمانی اضافه کنید.');return}const record={...meta,guestCount:meta.guests,menu:[...state.partyMenu],guestList:[...state.partyGuests],savedAt:new Date().toISOString()};const idx=state.parties.findIndex(p=>p.id===meta.id);if(idx>=0)state.parties[idx]=record;else state.parties.unshift(record);state.partyMeta=meta;saveState();renderSavedParties();renderReports();renderDashboard();renderActivityHistory();notify('مهمانی ذخیره شد و در آرشیو باقی می‌ماند.')}
function renderSavedParties(){const el=$('#savedParties');if(!el)return;el.innerHTML=state.parties.length?state.parties.map(p=>`<div class="saved-row"><div><b>${escapeHtml(p.name)}</b><small>${escapeHtml(isoToJalaliInput(p.date))} · ${escapeHtml(p.meal)} · ${fa(p.guestCount??(Array.isArray(p.guests)?p.guests.length:p.guests))} مهمان · ${(p.menu||[]).length} غذا</small></div><div><button data-load-party="${p.id}">بازکردن</button> <button data-delete-party="${p.id}">حذف</button></div></div>`).join(''):'<div class="empty-state">هنوز مهمانی ذخیره نشده است.</div>'}
function savedPartyAction(e){const load=e.target.closest('[data-load-party]'),del=e.target.closest('[data-delete-party]');if(load){const p=state.parties.find(x=>x.id===load.dataset.loadParty);if(!p)return;state.partyMeta={...p};state.partyMenu=[...(p.menu||[])];state.partyGuests=[...(p.guestList|| (Array.isArray(p.guests)?p.guests:[]))];$('#partyName').value=p.name;$('#guestCount').value=(p.guestCount??(Array.isArray(p.guests)?p.guests.length:p.guests))||8;$('#partyDate').value=isoToJalaliInput(p.date);$('#partyMeal').value=p.meal;$('#partyType').value=p.type;$('#partyStyle').value=p.style;$('#partyBudget').value=p.budget||'';$('#partyNotes').value=p.notes||'';saveState();renderPartyMenu();renderGuests();notify('مهمانی قبلی بارگذاری شد.');window.scrollTo({top:0,behavior:'smooth'})}if(del){if(!confirm('این مهمانی از آرشیو حذف شود؟'))return;state.parties=state.parties.filter(x=>x.id!==del.dataset.deleteParty);saveState();renderSavedParties();renderReports();renderDashboard()}}
function clearPartyForm(){if(!confirm('فرم و منوی فعلی پاک شود؟'))return;$('#partyForm').reset();$('#partyDate').value=isoToJalaliInput(isoToday());state.partyMeta=null;state.partyMenu=[];state.partyGuests=[];saveState();renderPartyMenu();renderGuests();renderSavedParties()}
function partyToShopping(){const meta=state.partyMeta||readPartyMeta();if(!state.partyMenu.length){notify('ابتدا غذاهای منو را انتخاب کنید.');return}const added=[];state.partyMenu.map(id=>recipes.find(r=>r.id===id)).filter(Boolean).forEach(r=>r.ingredients.forEach(i=>{const exists=state.shopping.some(x=>x.name===i[0]&&!x.done&&x.source==='party');if(!exists){state.shopping.push({id:uid(),name:i[0],qty:`${estimateIngredientQty(i[1],i[2],meta.guests)} · برآورد برای ${meta.guests} مهمان` ,category:guessShopCategory(i[0]),price:0,done:false,source:'party',partyName:meta.name,createdAt:isoToday()});added.push(i[0])}}));saveState();renderShopping();notify(`${fa(added.length)} قلم به فهرست خرید اضافه شد. مقدارها تقریبی‌اند؛ با تعداد مهمانان تطبیق دهید.`);showView('shopping')}
function guessShopCategory(name){const n=String(name||'');if(/زعفران|هل|دارچین|زردچوبه|فلفل سیاه|ادویه|نمک|زیره|پاپریکا|گلاب|وانیل|آویشن|نعناع خشک/.test(n))return 'ادویه‌جات و معطرات';if(/خیار|گوجه|پیاز|سبزی|هویج|کدو|کاهو|قارچ|بادمجان|سیب|موز|فلفل دلمه|کرفس|جعفری|پرتقال|لیمو|طالبی|هندوانه|توت.?فرنگی|کلم|اسفناج|کاهو|ذرت/.test(n))return 'میوه‌جات و صیفی‌جات';if(/شیر|ماست|پنیر|کشک|کره|خامه|دوغ|بستنی/.test(n))return 'لبنیات و سوپرمارکتی';if(/مرغ|گوشت|ماهی|میگو|تخم.?مرغ|بوقلمون|سوسیس|کالباس/.test(n))return 'پروتئینی و گوشت';if(/برنج|جو|آرد|عدس|لوبیا|نخود|ماکارونی|نان|روغن|لپه|بلغور|گندم|جوپرک|شکر|عسل|رب گوجه|خرما|گردو|بادام|فندق|کنجد|ارده/.test(n))return /نان/.test(n)?'نان و شیرینی':'خواربار و حبوبات';return 'سایر'}
function addQuickEssential(name){const people=Math.max(1,state.family.length||1);const quantities={'نان':`${people} عدد (تقریبی)`, 'شیر':`${Math.max(1,people*0.5)} لیتر (تقریبی)`, 'تخم‌مرغ':`${people*2} عدد (تقریبی)`, 'پیاز':`${Math.max(0.5,people*0.25)} کیلوگرم (تقریبی)`, 'سیب‌زمینی':`${Math.max(1,people*0.3).toFixed(1)} کیلوگرم (تقریبی)`, 'رب گوجه‌فرنگی':'۱ قوطی (تقریبی)', 'زعفران زر گل سپهران':'۱ بسته کوچک (تقریبی)'};const exists=state.shopping.some(i=>i.name===name&&!i.done);if(exists){notify('این قلم در فهرست خریدِ باقی‌مانده وجود دارد.');return}state.shopping.push({id:uid(),name,qty:quantities[name]||'',category:guessShopCategory(name),price:0,done:false,source:'quick',createdAt:isoToday()});saveState();renderShopping();notify(`«${name}» با مقدار پیشنهادی برای ${fa(people)} عضو خانواده افزوده شد؛ مقدار را بررسی کنید.`)}
function weeklyToShopping(){const used=new Set();const added=[];Object.values(state.weekly||{}).forEach(day=>Object.values(day||{}).forEach(id=>{const r=recipes.find(x=>x.id===id);if(!r)return;r.ingredients.forEach(i=>{const key=String(i[0]).trim().toLowerCase();if(used.has(key))return;used.add(key);const exists=state.shopping.some(x=>String(x.name).trim().toLowerCase()===key&&!x.done&&x.source==='weekly');if(!exists){state.shopping.push({id:uid(),name:i[0],qty:`${estimateIngredientQty(i[1],i[2],Math.max(1,state.family.length||2))} · برآورد برای ${Math.max(1,state.family.length||2)} عضو` ,category:guessShopCategory(i[0]),price:0,done:false,source:'weekly',recipeName:r.name,createdAt:isoToday()});added.push(i[0])}})}));if(!added.length){notify('برای برنامه هفتگی مواد جدیدی پیدا نشد؛ برنامه را تکمیل کنید یا فهرست را بررسی کنید.');return}saveState();renderShopping();notify(`${fa(added.length)} قلم از برنامه هفتگی به فهرست خرید افزوده شد؛ مقدارها تقریبی‌اند.`);showView('shopping')}
function printParty(){if(!state.partyMenu.length){notify('منوی مهمانی خالی است.');return}const p=state.partyMeta||readPartyMeta();const list=state.partyMenu.map(id=>recipes.find(r=>r.id===id)).filter(Boolean);const body=`<p><b>عنوان:</b> ${escapeHtml(p.name||'مهمانی')} | <b>تاریخ:</b> ${escapeHtml(isoToJalaliInput(p.date)||p.date)} | <b>تعداد مهمان:</b> ${fa(p.guests)} | <b>وعده:</b> ${escapeHtml(p.meal)} | <b>نوع:</b> ${escapeHtml(p.type)}</p><h2>منوی مهمانی</h2><ol>${list.map(r=>`<li>${escapeHtml(r.name)} — ${escapeHtml(r.category)}</li>`).join('')}</ol><h2>یادداشت</h2><p>${escapeHtml(p.notes||'—')}</p>`;printHtmlDocument('منوی مهمانی: '+(p.name||'غذایار'),body)}
function inventoryLocation(i){return i.location||'کابینت و انباری'}
function normalizedIngredient(s){return String(s||'').toLowerCase().replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/‌/g,' ').replace(/[،,؛;()[\]ـ]/g,' ').replace(/\s+/g,' ').trim()}
function inventoryHas(ingredient,names){const target=normalizedIngredient(ingredient);return names.some(n=>{const name=normalizedIngredient(n);return name===target||name.includes(target)||target.includes(name)||((target.includes('مرغ')&&name.includes('مرغ')))||((target.includes('برنج')&&name.includes('برنج')))||((target.includes('پیاز')&&name.includes('پیاز')))||((target.includes('روغن')&&name.includes('روغن')))||((target.includes('زعفران')&&name.includes('زعفران')))||((target.includes('تخم مرغ')||target.includes('تخم‌مرغ'))&&(name.includes('تخم مرغ')||name.includes('تخم‌مرغ')))} )}
function addInventoryQuick(name){if(state.inventory.some(i=>normalizedIngredient(i.name)===normalizedIngredient(name))){notify('این ماده از قبل در موجودی ثبت شده است.');return}const loc=/شیر|تخم‌مرغ/.test(name)?'یخچال':/زعفران|برنج|روغن|نمک/.test(name)?'کابینت و انباری':'کابینت و انباری';state.inventory.push({id:uid(),name,group:/شیر|تخم‌مرغ/.test(name)?'لبنیات':/برنج/.test(name)?'غلات':/زعفران|نمک/.test(name)?'چاشنی':'سایر',location:loc,qty:'',purchaseDate:'',expiryDate:'',createdAt:isoToday()});saveState();renderInventory();notify(`«${name}» به موجودی ${loc} افزوده شد.`)}
function renderInventory(){if(!$('#inventoryList'))return;const locations=['یخچال','فریزر','کابینت و انباری'];const body=locations.map(loc=>{const items=state.inventory.filter(i=>inventoryLocation(i)===loc);if(!items.length)return '';const icon=loc==='یخچال'?'🥬':loc==='فریزر'?'🧊':'🏺';return `<section class="inventory-location-group"><h4>${icon} ${loc} <small>(${fa(items.length)} قلم)</small></h4><div class="inventory-chip-list">${items.map(i=>{const exp=i.expiryDate?`<small class="inventory-date ${daysUntil(i.expiryDate)<=2?'expiry-soon':''}">${daysUntil(i.expiryDate)<0?'منقضی‌شده':`انقضا: ${escapeHtml(isoToJalaliInput(i.expiryDate))}`}</small>`:'';return `<span class="inventory-chip"><span><b>${escapeHtml(i.name)}</b>${i.qty?`<small>${escapeHtml(i.qty)}</small>`:''}${i.purchaseDate?`<small>خرید: ${escapeHtml(isoToJalaliInput(i.purchaseDate))}</small>`:''}${exp}</span><button aria-label="حذف ${escapeHtml(i.name)}" data-remove-inventory="${i.id}">×</button></span>`}).join('')}</div></section>`}).join('');$('#inventoryList').innerHTML=body||'<small class="hint">هنوز ماده‌ای ثبت نشده است.</small>';renderInventoryExpiryAlerts()}
function daysUntil(iso){if(!iso)return 99999;const today=new Date(isoToday()+'T00:00:00Z'),d=new Date(iso+'T00:00:00Z');return Math.round((d-today)/86400000)}
function renderInventoryExpiryAlerts(){const el=$('#inventoryExpiryAlerts');if(!el)return;const soon=state.inventory.filter(i=>i.expiryDate&&daysUntil(i.expiryDate)<=3).sort((a,b)=>a.expiryDate.localeCompare(b.expiryDate));if(!soon.length){el.innerHTML='';return}const names=soon.slice(0,5).map(i=>i.name);const matching=recipes.filter(r=>r.ingredients.length&&r.ingredients.some(ing=>inventoryHas(ing[0],names)));el.innerHTML=`<div class="inventory-alert-panel"><b>⏰ توجه به تاریخ مصرف</b><p>${soon.map(i=>`${escapeHtml(i.name)}: ${daysUntil(i.expiryDate)<0?'تاریخ ثبت‌شده گذشته است':daysUntil(i.expiryDate)===0?'امروز':`تا ${fa(daysUntil(i.expiryDate))} روز دیگر`}`).join(' · ')}</p>${matching.length?`<small>پیشنهاد برای استفاده از این مواد: ${matching.slice(0,3).map(r=>escapeHtml(r.name)).join('، ')}</small>`:''}<small class="hint">این هشدار صرفاً بر اساس تاریخی است که وارد کرده‌اید؛ سلامت واقعی ماده را پیش از مصرف بررسی کنید.</small></div>`}
function renderInventorySuggestions(){const names=state.inventory.map(i=>i.name);if(!names.length){notify('ابتدا مواد موجود را ثبت کنید.');return}const list=recipes.filter(r=>r.ingredients.length).map(r=>{const haveItems=r.ingredients.filter(i=>inventoryHas(i[0],names));const missing=r.ingredients.filter(i=>!inventoryHas(i[0],names));return {r,have:haveItems.length,total:r.ingredients.length,missing,percent:r.ingredients.length?Math.round(haveItems.length/r.ingredients.length*100):0}}).filter(x=>x.have>0).sort((a,b)=>b.percent-a.percent||a.missing.length-b.missing.length);$('#inventorySuggestions').classList.remove('empty-state');$('#inventorySuggestions').innerHTML=list.length?list.slice(0,20).map(x=>`<div class="suggestion-row inventory-suggestion"><span class="food-emoji">${x.percent===100?'🟢':x.percent>=80?'🟡':x.r.emoji}</span><div class="suggestion-content"><b>${escapeHtml(x.r.name)}</b><small><span class="match-badge ${x.percent===100?'match-full':x.percent>=80?'match-high':'match-partial'}">${fa(x.percent)}٪ تطابق</span> · ${fa(x.have)} از ${fa(x.total)} ماده موجود</small><small>${x.percent===100?'همه مواد ثبت‌شده در موجودی هستند؛ می‌توانید برای پخت آماده شوید.':`مواد کسری: ${x.missing.map(i=>escapeHtml(i[0])).join('، ')}`}</small></div><div class="suggestion-actions"><button data-open-recipe="${x.r.id}">دستور پخت</button>${x.missing.length?`<button class="missing-add-btn" data-add-missing="${x.r.id}">افزودن مواد کسری</button>`:''}</div></div>`).join(''):'با مواد فعلی تطبیق مناسبی پیدا نشد.'}
function addMissingIngredients(recipeId){const r=recipes.find(x=>x.id===recipeId);if(!r)return;const names=state.inventory.map(i=>i.name);const missing=r.ingredients.filter(i=>!inventoryHas(i[0],names));let count=0;missing.forEach(i=>{const exists=state.shopping.some(x=>normalizedIngredient(x.name)===normalizedIngredient(i[0])&&!x.done);if(!exists){state.shopping.push({id:uid(),name:i[0],qty:`${i[1]} ${i[2]}`,category:guessShopCategory(i[0]),price:0,done:false,source:'inventory-missing',recipeName:r.name,createdAt:isoToday()});count++}});saveState();renderShopping();notify(count?`${fa(count)} ماده کسری برای «${r.name}» به فهرست خرید اضافه شد.`:'مواد کسری این غذا از قبل در فهرست خرید هستند.');}
function addRecipeIngredientsToShopping(r){let count=0;r.ingredients.forEach(i=>{if(!state.shopping.some(x=>x.name===i[0]&&!x.done)){state.shopping.push({id:uid(),name:i[0],qty:`${i[1]} ${i[2]}`,category:guessShopCategory(i[0]),price:0,done:false,source:'recipe',recipeName:r.name,createdAt:isoToday()});count++}});saveState();renderShopping();notify(`${fa(count)} ماده به فهرست خرید اضافه شد.`)}
function sourceLabel(source){return ({weekly:'برنامه هفتگی',party:'مهمانی‌یار',manual:'دستی',recipe:'دستور پخت',quick:'افزودن سریع','inventory-missing':'مواد کسری موجودی'})[source]||'دستی'}
function normalizeShopCategory(category,name){const old={'سبزیجات و میوه':'میوه‌جات و صیفی‌جات','میوه و سبزی':'میوه‌جات و صیفی‌جات','لبنیات':'لبنیات و سوپرمارکتی','گوشت و پروتئین':'پروتئینی و گوشت','حبوبات و غلات':'خواربار و حبوبات'};if(category==='چاشنی و سایر'||!category||category==='auto')return guessShopCategory(name);return old[category]||(['میوه‌جات و صیفی‌جات','پروتئینی و گوشت','خواربار و حبوبات','لبنیات و سوپرمارکتی','ادویه‌جات و معطرات','نان و شیرینی','سایر'].includes(category)?category:guessShopCategory(name))}
function estimateIngredientQty(value,unit,people){const n=Number(value);if(!Number.isFinite(n)||!unit||/به مقدار لازم|مقدار/.test(String(unit))||n<=0)return `${value} ${unit||''}`.trim();const scaled=n*Math.max(1,people)/4;const amount=Number(scaled.toFixed(1)).toLocaleString('fa-IR');return `${amount} ${unit} (برآورد بر پایه دستور ۴ نفره)`}
function renderShopping(){const el=$('#shoppingList');if(!el)return;const checked=state.shopping.filter(i=>i.done).length;$('#shoppingProgressText').textContent=`${fa(checked)} از ${fa(state.shopping.length)} قلم خریداری شده`;$('#shoppingProgressBar').style.width=state.shopping.length?`${checked/state.shopping.length*100}%`:'0%';const total=state.shopping.reduce((sum,i)=>sum+Math.max(0,Number(i.price)||0),0);$('#shoppingTotalCost').textContent=`${fa(total)} تومان`;const catFilter=$('#shoppingCategoryFilter')?.value||'all',srcFilter=$('#shoppingSourceFilter')?.value||'all';const items=state.shopping.map(i=>({...i,category:normalizeShopCategory(i.category,i.name),source:i.source||'manual'})).filter(i=>(catFilter==='all'||i.category===catFilter)&&(srcFilter==='all'||i.source===srcFilter));const groups=['میوه‌جات و صیفی‌جات','پروتئینی و گوشت','خواربار و حبوبات','لبنیات و سوپرمارکتی','ادویه‌جات و معطرات','نان و شیرینی','سایر'];el.classList.toggle('empty-state',!items.length);el.innerHTML=items.length?groups.filter(g=>items.some(i=>i.category===g)).map(g=>`<section class="shopping-group"><h3>${({'میوه‌جات و صیفی‌جات':'🥦','پروتئینی و گوشت':'🥩','خواربار و حبوبات':'🌾','لبنیات و سوپرمارکتی':'🥛','ادویه‌جات و معطرات':'👑','نان و شیرینی':'🍞','سایر':'🧺'})[g]} ${g}</h3>${items.filter(i=>i.category===g).map(i=>`<div class="shopping-row"><input type="checkbox" data-shopping-check="${i.id}" ${i.done?'checked':''}><div class="shopping-item-main"><span class="item-name ${i.done?'done':''}">${escapeHtml(i.name)}</span><small>${escapeHtml(i.qty||'مقدار مشخص نشده')}</small><span class="source-tag source-${escapeHtml(i.source)}">🏷️ ${sourceLabel(i.source)}</span></div><label class="shopping-price-field"><span>هزینه (تومان)</span><input type="number" min="0" step="1000" value="${Math.max(0,Number(i.price)||0)||''}" placeholder="۰" data-shopping-price="${i.id}" aria-label="هزینه ${escapeHtml(i.name)}"></label><button data-remove-shopping="${i.id}">حذف</button></div>`).join('')}</section>`).join(''):'فهرستی با این فیلترها پیدا نشد.';$('#statShopping').textContent=fa(state.shopping.filter(i=>!i.done).length)}
function exportShopping(){download('ghazayar-shopping.csv','\ufeff'+csv(['قلم','مقدار','دسته','هزینه تقریبی (تومان)','خریداری‌شده','منبع'],state.shopping.map(i=>[i.name,i.qty,normalizeShopCategory(i.category,i.name),i.price||0,i.done?'بله':'خیر',sourceLabel(i.source)])),'text/csv;charset=utf-8');notify('فهرست خرید به CSV صادر شد.')}
function shoppingText(){const groups={};state.shopping.forEach(i=>{const cat=normalizeShopCategory(i.category,i.name);(groups[cat]||(groups[cat]=[])).push(`• ${i.name}${i.qty?' — '+i.qty:''}${Number(i.price)>0?' — حدود '+fa(i.price)+' تومان':''}${i.done?' (خریداری‌شده)':''} [${sourceLabel(i.source)}]`)});return 'فهرست خرید غذایار\n'+Object.entries(groups).map(([g,rows])=>`\n${g}\n${rows.join('\n')}`).join('')+`\n\nمجموع هزینه تقریبی اقلام: ${fa(state.shopping.reduce((s,i)=>s+Math.max(0,Number(i.price)||0),0))} تومان` }
async function copyShoppingText(){const text=shoppingText();try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();const ok=document.execCommand('copy');ta.remove();if(!ok)throw Error('copy failed')}notify('متن فهرست خرید کپی شد؛ می‌توانید آن را در پیامک یا پیام‌رسان بچسبانید.')}catch{prompt('متن فهرست خرید را کپی کنید:',text)}}
async function shareShoppingText(){const text=shoppingText();if(navigator.share){try{await navigator.share({title:'فهرست خرید غذایار',text});notify('پنجره اشتراک‌گذاری دستگاه باز شد؛ پیام‌رسان موردنظر را انتخاب کنید.')}catch(e){if(e?.name!=='AbortError')notify('اشتراک‌گذاری انجام نشد؛ از دکمه «کپی متن فهرست» استفاده کنید.')}}else{await copyShoppingText();notify('در این مرورگر اشتراک‌گذاری مستقیم در دسترس نیست؛ متن کپی‌شده را در واتساپ، تلگرام، ایتا یا بله بچسبانید.')}}
function renderFamily(){const el=$('#familyList');if(!el)return;el.classList.toggle('empty-state',!state.family.length);el.innerHTML=state.family.length?state.family.map(m=>`<article class="family-card"><div class="family-card-head"><b>♧ ${escapeHtml(m.name)} · ${fa(m.age)} سال</b><button data-remove-family="${m.id}">حذف</button></div><p>جنسیت: ${escapeHtml(m.gender)} · سلامت: ${escapeHtml(m.health)}<br>الگوی غذایی: ${escapeHtml(m.diet)} · فعالیت: ${escapeHtml(m.activity)}<br>هدف تغذیه‌ای: ${escapeHtml(goalLabel(m.goal))}<br>طبع ثبت‌شده: ${escapeHtml(m.temperament||'مشخص نشده')}<br>سبک غذا: ${escapeHtml(m.texture||'همه سبک‌ها')}<br>وعده محبوب: ${escapeHtml(m.favoriteMeal||'بدون ترجیح مشخص')}<br>علاقه‌ها: ${escapeHtml((m.likes||[]).join('، ')||'ثبت نشده')}<br>پرهیزها/حساسیت‌ها: ${escapeHtml((m.avoid||[]).join('، ')||'ثبت نشده')}</p></article>`).join(''):'هنوز عضوی ثبت نشده است.';const sel=$('#smartMember');if(sel){const v=sel.value;sel.innerHTML='<option value="all">همه اعضای خانواده</option>'+state.family.map(m=>`<option value="${m.id}">${escapeHtml(m.name)}</option>`).join('');if([...sel.options].some(o=>o.value===v))sel.value=v;}}
function goalLabel(goal){return ({gain:'افزایش وزن / عضله‌سازی',loss:'کاهش وزن / چربی‌سوزی',maintain:'تثبیت وزن و حفظ سلامت عمومی',glucose:'کنترل قند خون / انسولین',plant:'الگوی گیاهی متنوع'})[goal]||'تثبیت وزن و حفظ سلامت عمومی'}
function renderSmartMenu(){const out=$('#smartMenuResults');if(!out)return;const memberId=$('#smartMember')?.value||'all',audience=$('#smartAudience')?.value||'personal';let members=state.family.filter(m=>memberId==='all'||m.id===memberId);let member=members[0]||null;if(audience==='child')members=state.family.filter(m=>Number(m.age)<=18);else if(audience==='elderly')members=state.family.filter(m=>Number(m.age)>=60||m.health==='سالمند');else if(audience==='sport')members=state.family.filter(m=>m.activity==='ورزشکار'||m.goal==='gain');else if(audience==='health')members=state.family.filter(m=>['دیابت','فشار خون بالا','بیماری قلبی','سالمند'].includes(m.health)||m.diet==='low-salt');if(audience!=='personal'&&memberId!=='all'&&member)members=[member];const target=memberId==='all'?(audience==='personal'?null:(members[0]||null)):(members[0]||member);const avoidMembers=memberId==='all'&&audience==='personal'?state.family:(target?[target]:[]);const pool=recipes.filter(r=>!avoidMembers.some(m=>(m.avoid||[]).map(x=>x.toLocaleLowerCase()).filter(Boolean).some(a=>r.ingredients.some(i=>String(i[0]).toLocaleLowerCase().includes(a)||a.includes(String(i[0]).toLocaleLowerCase())))));const keywords=audience==='child'?['شیر','موز','فرنی','وافل','میوه','گرانولا','تخم‌مرغ','ماست']:audience==='elderly'||audience==='health'?['سوپ','سبزی','مرغ','سالاد','بخارپز','کینوآ','دمنوش','کم‌نمک','ماهی']:audience==='sport'?['مرغ','گوشت','تخم‌مرغ','گرانولا','اسموتی','ماست','لوبیا','عدس']:[];const goal=target?.goal||'maintain';const texture=target?.texture||'';const likes=(target?.likes||[]).join(' ').toLocaleLowerCase();const scored=pool.map(r=>{let score=0;const text=(r.name+' '+r.description+' '+r.category+' '+r.ingredients.map(i=>i[0]).join(' ')).toLocaleLowerCase();keywords.forEach(k=>{if(text.includes(k))score+=3});if(target){if(likes&&likes.includes(r.name.toLocaleLowerCase()))score+=8;if(r.category==='صبحانه'&&target.favoriteMeal==='صبحانه مفصل')score+=3;if(r.category==='میان‌وعده'&&String(target.favoriteMeal).includes('میان‌وعده'))score+=4;if(goal==='gain'&&/مرغ|گوشت|تخم.?مرغ|گردو|بادام|لوبیا|عدس|ماست/.test(text))score+=2;if(goal==='loss'&&/سالاد|سوپ|سبزی|بخارپز|کم.?روغن/.test(text))score+=2;if(goal==='plant'&&(/گیاهی|سبزی|عدس|لوبیا|نخود|سالاد|میوه/.test(text)||r.diets.includes('vegan')))score+=2;if(goal==='glucose'&&/سالاد|سبزی|حبوبات|مرغ|ماهی|تخم.?مرغ/.test(text))score+=2;if(texture.includes('سوپ')&&/سوپ|آش|خورش|آبگوشت/.test(text))score+=2;if(texture.includes('سنتی')&&/پلو|چلو|خورش|کباب|نان/.test(text))score+=2;if(texture.includes('سالاد')&&/سالاد|پیش.?غذا|میوه/.test(text))score+=2;if(texture.includes('بخارپز')&&/بخارپز|مرغ|سبزی|ماهی|سوپ/.test(text))score+=2;if(target.temperament&&target.temperament.startsWith('سرد')&&/زعفران|دارچین|زنجبیل|هل/.test(text))score+=1;if(target.activity==='ورزشکار'&&/مرغ|گوشت|تخم.?مرغ|ماست|عدس|لوبیا/.test(text))score+=2;if(target.health==='دیابت'&&r.tags.includes('diabetes'))score+=4;if(target.health==='فشار خون بالا'&&r.tags.includes('low-salt'))score+=4;if(target.health==='بیماری قلبی'&&r.tags.includes('heart'))score+=4;}return {r,score}}).sort((a,b)=>b.score-a.score).slice(0,6).map(x=>x.r);const heading=audience==='child'?'پیشنهادهای کودکان و دانش‌آموزان':audience==='elderly'?'پیشنهادهای سالمندان':audience==='health'?'ایده‌های سبک و کم‌نمک':audience==='sport'?'ایده‌های پروتئینی برای ورزشکاران':'پیشنهادهای متناسب با خانواده';let html=`<h3>${heading}${target?' · '+escapeHtml(target.name):''}</h3><p class="muted">پیشنهادها بر اساس اطلاعات موجود در کتابخانه مرتب شده‌اند؛ اگر اطلاعات مواد یا برچسب رژیمی غذا کامل نباشد، این رتبه‌بندی قطعی نیست.</p>`;if(!state.family.length&&audience==='personal')html+='<p>برای شخصی‌سازی، ابتدا از بخش «خانواده و سلیقه‌ها» حداقل یک عضو ثبت کنید.</p>';html+=scored.length?scored.map(r=>`<div class="suggestion-row"><span class="food-emoji">${r.emoji||'🍽️'}</span><div><b>${escapeHtml(r.name)}</b><small>${escapeHtml(r.category)} · زمان تقریبی ${fa(r.time)} دقیقه</small></div><button data-open-recipe="${r.id}">دستور تهیه</button></div>`).join(''):'<p>با توجه به فهرست پرهیزها موردی پیدا نشد؛ پرهیزها را بازبینی کنید.</p>';const cold=target&&(String(target.temperament||'').startsWith('سرد')||scored.some(r=>/ماهی|برنج|چلو|پلو/.test(r.name)));if(cold)html+=`<div class="complementary-note"><b>پیشنهاد مصلح بر پایه سنت غذایی (اختیاری)</b><p>در برخی سنت‌های غذایی، زعفران، دارچین یا هل همراه بعضی غذاها پیشنهاد می‌شوند. می‌توانید متناسب با ذائقه، ته‌چین زعفرانی یا شربت زعفران و هل زر گل سپهران را در نظر بگیرید؛ این پیشنهاد ادعای اثر درمانی ندارد و شربت شیرین برای افراد نیازمند کنترل قند باید با احتیاط بررسی شود.</p></div>`;if(target&&['دیابت','فشار خون بالا','بیماری قلبی'].includes(target.health))html+='<p class="disclaimer">برای وضعیت ثبت‌شده، این فهرست فقط ایده غذایی است؛ میزان نمک، قند، چربی و اندازه سهم باید با توصیه درمانگر هماهنگ شود.</p>';out.innerHTML=html;}
function renderReports(){if(!$('#reportResults'))return;const from=isoFromJalali($('#reportFrom').value)||'',to=isoFromJalali($('#reportTo').value)||'',type=$('#reportType').value;const parties=state.parties.filter(p=>(!from||p.date>=from)&&(!to||p.date<=to));const weeks=state.weekArchives.filter(w=>(!from||w.weekStart>=from)&&(!to||w.weekStart<=to));$('#reportPartyCount').textContent=fa(state.parties.length);$('#reportWeekCount').textContent=fa(state.weekArchives.length);$('#reportShoppingCount').textContent=fa(state.shopping.length);const out=[];if(type==='all'||type==='party')parties.forEach(p=>out.push({date:p.date,type:'party',title:`مهمانی: ${p.name}`,body:`${fa(p.guestCount??(Array.isArray(p.guests)?p.guests.length:p.guests))} مهمان · ${p.meal} · ${p.type} · غذاها: ${(p.menu||[]).map(id=>recipeLabel(id)).join('، ')||'منویی ثبت نشده'}`,id:p.id}));if(type==='all'||type==='week'){const currentMeals=Object.values(state.weekly||{}).reduce((n,day)=>n+Object.values(day||{}).filter(Boolean).length,0);const currentAllowed=currentMeals&&(!from||state.weekStart>=from)&&(!to||state.weekStart<=to);const archived=weeks.slice().sort((a,b)=>String(b.weekStart||'').localeCompare(String(a.weekStart||'')))[0];if(currentAllowed){const dayNames=['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'];const details=Object.entries(state.weekly||{}).map(([date,day],i)=>`${dayNames[i]||date}: ${Object.entries(day||{}).filter(([meal,id])=>id).map(([meal,id])=>`${meal}: ${recipeLabel(id)}`).join('، ')||'بدون وعده ثبت‌شده'}`).join('\n');out.push({date:state.weekStart,type:'week-current',title:'برنامه هفتگی',body:`${fa(currentMeals)} وعده ثبت‌شده\n${details}`,id:'current'})}else if(archived){const dayNames=['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'];const details=Object.entries(archived.meals||{}).map(([date,day],i)=>`${dayNames[i]||date}: ${Object.entries(day||{}).filter(([meal,id])=>id).map(([meal,id])=>`${meal}: ${recipeLabel(id)}`).join('، ')||'بدون وعده ثبت‌شده'}`).join('\n');const meals=Object.values(archived.meals||{}).reduce((a,day)=>a+Object.values(day||{}).filter(Boolean).length,0);out.push({date:archived.weekStart,type:'week',title:'برنامه هفتگی',body:`تعداد وعده‌های ثبت‌شده: ${fa(meals)}\n${details}`,id:archived.id})}}if(type==='all'||type==='shopping'){const items=state.shopping.filter(i=>(!from||!i.createdAt||i.createdAt>=from)&&(!to||!i.createdAt||i.createdAt<=to));if(items.length||type==='shopping')out.push({date:isoToday(),type:'shopping',title:'فهرست خرید فعلی',body:`${fa(items.length)} قلم؛ ${fa(items.filter(i=>i.done).length)} قلم خریداری شده؛ ${fa(items.filter(i=>!i.done).length)} قلم باقی‌مانده`,id:'shopping'})}$('#reportResults').innerHTML=out.length?out.sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<article class="report-card"><h3>${x.type==='party'?'✦':x.type.startsWith('week')?'▦':'🛒'} ${escapeHtml(x.title)}</h3><p>تاریخ: ${escapeHtml(isoToJalaliInput(x.date)||x.date)}</p><p class="report-body">${escapeHtml(x.body).replace(/\n/g,'<br>')}</p><div class="report-actions">${x.type==='party'?`<button data-report-party="${x.id}">بارگذاری مهمانی</button>`:''}${x.type==='week'?`<button data-report-week="${x.id}">بازیابی برنامه</button>`:''}<button data-print-report="${x.type==='week-current'?'week':x.type}" data-report-id="${x.id}">چاپ / ذخیره PDF</button><button data-share-report="${x.type}" data-report-id="${x.id}">اشتراک‌گذاری گزارش</button></div></article>`).join(''):'<div class="panel empty-state">برای این بازه گزارشی پیدا نشد. مهمانی یا برنامه هفتگی را ذخیره کنید تا در این بخش بماند.</div>';$('#reportResults').onclick=e=>{const print=e.target.closest('[data-print-report]');if(print){printReportItem(print.dataset.printReport,print.dataset.reportId);return}const share=e.target.closest('[data-share-report]');if(share){shareReportItem(share.dataset.shareReport,share.dataset.reportId);return}const p=e.target.closest('[data-report-party]'),w=e.target.closest('[data-report-week]');if(p){const rec=state.parties.find(x=>x.id===p.dataset.reportParty);if(rec){state.partyMeta={...rec};state.partyMenu=[...(rec.menu||[])];state.partyGuests=[...(rec.guestList||[])];saveState();showView('party');renderPartyMenu();notify('مهمانی بارگذاری شد.')}}if(w){const rec=state.weekArchives.find(x=>x.id===w.dataset.reportWeek);if(rec){state.weekly=JSON.parse(JSON.stringify(rec.meals));state.weekStart=rec.weekStart;$('#weekStart').value=isoToJalaliInput(state.weekStart);saveState();showView('weekly');renderWeek();notify('برنامه ذخیره‌شده بازیابی شد.')}}}} 
function printHtmlDocument(title,body){if(window.GhazayarNative?.printReport){window.GhazayarNative.printReport(title,body);return}const w=window.open('','_blank');if(!w){notify('مرورگر اجازه بازشدن پنجره گزارش را نداد. از دکمه اشتراک‌گذاری استفاده کنید یا اجازه پنجره‌های بازشو را فعال کنید.');return}const doc=`<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title><style>*{box-sizing:border-box}body{font-family:Tahoma,"Segoe UI",sans-serif;color:#20382e;line-height:2;margin:0;background:#f3f7f4;padding:22px}.sheet{max-width:900px;margin:auto;background:#fff;border:1px solid #dbe7de;border-radius:18px;overflow:hidden;box-shadow:0 12px 40px #163c2a14}.head{background:linear-gradient(125deg,#0e5944,#238667);color:white;padding:28px 34px;position:relative}.brand{font-size:13px;opacity:.9;letter-spacing:.2px}.head h1{font-size:28px;margin:4px 0;color:white}.head h2{font-size:18px;margin:0;color:#e6fff0;font-weight:500}.head .date{display:inline-block;margin-top:12px;border:1px solid #ffffff50;border-radius:20px;padding:2px 12px;font-size:11px}.content{padding:26px 34px 34px}h3{color:#176b55;border-right:4px solid #d2a95d;padding-right:10px;margin-top:25px}p,li{font-size:13px}table{width:100%;border-collapse:separate;border-spacing:0;margin:16px 0;border:1px solid #dbe7de;border-radius:10px;overflow:hidden}th,td{border-bottom:1px solid #e2ebe4;padding:10px 12px;text-align:right;font-size:12px}th{background:#e8f4ec;color:#155b45;font-weight:700}tr:nth-child(even) td{background:#fafcfb}tr:last-child td{border-bottom:0}.weekly-print-table{table-layout:fixed}.weekly-print-table td:first-child{width:28%;font-weight:700;color:#176b55}.weekly-print-table .day-row th{text-align:right;background:#d5ebdc;font-size:14px;padding:10px}.weekly-print-table .day-row small{font-size:10px;font-weight:400;color:#52665a}.weekly-print-table td{overflow-wrap:anywhere;padding:8px 10px}.footer{border-top:1px solid #e3ece5;padding:12px 34px;color:#74847a;font-size:10px;display:flex;justify-content:space-between;gap:10px}.actions{max-width:900px;margin:0 auto 14px;display:flex;gap:8px;flex-wrap:wrap}.actions button{border:0;border-radius:9px;padding:10px 15px;background:#176b55;color:#fff;font:inherit;cursor:pointer}.actions .close{background:#e8efea;color:#244536}.muted{color:#66766d}@page{size:A4;margin:12mm}@media print{body{background:#fff;padding:0}.sheet{max-width:none;border:0;border-radius:0;box-shadow:none}.head{-webkit-print-color-adjust:exact;print-color-adjust:exact}.actions{display:none}.content{padding:18px 22px}.footer{padding:10px 22px}table,li{break-inside:avoid}} </style></head><body><div class="actions"><button onclick="window.print()">چاپ / ذخیره به‌صورت PDF</button><button class="close" onclick="if(window.opener){window.close();window.opener.focus()}else{location.href='file:///android_asset/www/index.html'}">بازگشت به غذایار</button></div><article class="sheet"><header class="head"><div class="brand">🥗 غذایار | دستیار هوشمند آشپزخانه</div><h1>گزارش حرفه‌ای</h1><h2>${escapeHtml(title)}</h2><span class="date">تاریخ تهیه گزارش: ${escapeHtml(isoToJalaliInput(isoToday()))}</span></header><main class="content">${body}</main><footer class="footer"><span>تهیه‌شده با غذایار</span><span>پشتیبانی: esmlotfi@gmail.com</span></footer></article><script>window.addEventListener('afterprint',()=>{setTimeout(()=>{try{window.close()}catch(e){}if(window.opener){try{window.opener.focus()}catch(e){}}},250)});<\/script></body></html>`;w.document.open();w.document.write(doc);w.document.close();w.focus()}
function printShopping(){const items=state.shopping;const body=items.length?`<p>تعداد اقلام: ${fa(items.length)} · خریداری‌شده: ${fa(items.filter(i=>i.done).length)} · باقی‌مانده: ${fa(items.filter(i=>!i.done).length)} · مجموع هزینه تقریبی: ${fa(items.reduce((s,i)=>s+Math.max(0,Number(i.price)||0),0))} تومان</p><table><thead><tr><th>ردیف</th><th>قلم خرید</th><th>مقدار</th><th>دسته‌بندی</th><th>هزینه تقریبی (تومان)</th><th>منبع</th><th>وضعیت</th></tr></thead><tbody>${items.map((i,n)=>`<tr><td>${fa(n+1)}</td><td>${escapeHtml(i.name)}</td><td>${escapeHtml(i.qty||'—')}</td><td>${escapeHtml(normalizeShopCategory(i.category,i.name))}</td><td>${fa(i.price||0)}</td><td>${sourceLabel(i.source)}</td><td>${i.done?'خریداری شده':'باقی‌مانده'}</td></tr>`).join('')}</tbody></table>`:'<p>فهرست خرید فعلی خالی است.</p>';printHtmlDocument('فهرست خرید برای چاپ',body)}
function weekMealCount(meals){return Object.values(meals||{}).reduce((n,day)=>n+Object.values(day||{}).filter(Boolean).length,0)}
function weekArchiveDetails(meals){return Object.entries(meals||{}).map(([date,day])=>`<div class="history-day"><b>${escapeHtml(isoToJalaliInput(date)||date)}</b><span>${Object.entries(day||{}).filter(([meal,id])=>id).map(([meal,id])=>`${escapeHtml(meal)}: ${escapeHtml(recipes.find(r=>r.id===id)?.name||String(id))}`).join(' · ')||'بدون وعده'}</span></div>`).join('')}
function renderActivityHistory(){if(!$('#historyWeekArchive'))return;const weeks=[...(state.weekArchives||[])].sort((a,b)=>String(b.weekStart||'').localeCompare(String(a.weekStart||''))||String(b.savedAt||'').localeCompare(String(a.savedAt||'')));$('#historyWeekCount').textContent=`${fa(weeks.length)} برنامه`;$('#historyWeekArchive').innerHTML=weeks.length?weeks.map(w=>`<article class="history-card"><div class="history-card-main"><div><b>برنامه هفته ${escapeHtml(isoToJalaliInput(w.weekStart)||w.weekStart||'—')}</b><small>ذخیره: ${escapeHtml(w.savedAt?new Date(w.savedAt).toLocaleDateString('fa-IR'):'—')} · ${fa(weekMealCount(w.meals))} وعده چیده‌شده</small></div><div class="history-actions"><button data-week-details="${w.id}" class="secondary-btn">جزئیات</button><button data-week-load="${w.id}" class="secondary-btn">بارگذاری</button><button data-week-edit="${w.id}" class="secondary-btn">ویرایش</button><button data-week-delete="${w.id}" class="danger-btn secondary-btn">حذف</button></div></div><div class="history-details" id="weekDetails-${w.id}" hidden>${weekArchiveDetails(w.meals)}</div></article>`).join(''):'<div class="empty-state">هنوز برنامه هفتگی ذخیره‌شده‌ای وجود ندارد. از صفحه «برنامه هفتگی» دکمه «ذخیره برنامه» را بزنید.</div>';renderHistoryParties();renderMonthlyNutrition()}
function historyWeekAction(e){const b=e.target.closest('button');if(!b)return;const id=b.dataset.weekDetails||b.dataset.weekLoad||b.dataset.weekEdit||b.dataset.weekDelete;const rec=state.weekArchives.find(x=>x.id===id);if(!rec)return;if(b.dataset.weekDetails){const panel=$(`#weekDetails-${CSS.escape(id)}`);if(panel)panel.hidden=!panel.hidden;return}if(b.dataset.weekDelete){if(!confirm('این برنامه از آرشیو حذف شود؟ این کار برنامه فعلی را پاک نمی‌کند.'))return;state.weekArchives=state.weekArchives.filter(x=>x.id!==id);state.savedPlans=(state.savedPlans||[]).filter(x=>x.id!==id);saveState();renderActivityHistory();renderReports();notify('برنامه از آرشیو حذف شد.');return}state.weekly=JSON.parse(JSON.stringify(rec.meals||{}));state.weekStart=rec.weekStart||isoToday();$('#weekStart').value=isoToJalaliInput(state.weekStart);editingWeekArchiveId=b.dataset.weekEdit?id:null;saveState();showView('weekly');renderWeek();notify(b.dataset.weekEdit?'برنامه برای ویرایش باز شد؛ پس از تغییر، «ذخیره برنامه» را بزنید.':'برنامه آرشیوشده بارگذاری شد.');}
function renderHistoryParties(){if(!$('#historyPartyArchive'))return;const raw=String($('#historyPartySearch')?.value||'').trim().toLowerCase();const norm=raw.replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/[.\-]/g,'/');const dateParts=norm.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);const isoSearch=isoFromJalali(dateParts?`${dateParts[3]}/${dateParts[2]}/${dateParts[1]}`:norm);const type=$('#historyPartyType')?.value||'all';const rows=[...(state.parties||[])].filter(p=>(type==='all'||p.type===type)&&(!raw||String(p.name||'').toLowerCase().includes(raw)||String(p.type||'').toLowerCase().includes(raw)||String(isoToJalaliInput(p.date)||'').replace(/-/g,'/').includes(norm)||String(p.date||'')===isoSearch)).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));$('#historyPartyCount').textContent=`${fa(rows.length)} مهمانی`;$('#historyPartyArchive').innerHTML=rows.length?rows.map(p=>{const menu=(p.menu||[]).map(id=>recipeLabel(id));return `<article class="history-card"><div class="history-card-main"><div><b>🎉 ${escapeHtml(p.name||'مهمانی بدون عنوان')}</b><small>${escapeHtml(isoToJalaliInput(p.date)||p.date||'—')} · ${escapeHtml(p.type||'نوع نامشخص')} · ${fa(p.guestCount ?? (Array.isArray(p.guests) ? p.guests.length : (p.guests || 0)))} مهمان · ${fa(menu.length)} قلم منو</small><small>منو: ${escapeHtml(menu.join('، ')||'منویی ثبت نشده')}</small></div><div class="history-actions"><button class="secondary-btn" data-party-details="${p.id}">جزئیات</button><button class="secondary-btn" data-party-load="${p.id}">بارگذاری / ویرایش</button><button class="secondary-btn danger-btn" data-party-delete="${p.id}">حذف</button></div></div><div class="history-details" id="partyDetails-${p.id}" hidden><p>عنوان: ${escapeHtml(p.name||'—')}</p><p>تاریخ: ${escapeHtml(isoToJalaliInput(p.date)||p.date||'—')} · وعده: ${escapeHtml(p.meal||'—')} · سبک: ${escapeHtml(p.style||'—')}</p><p>تعداد مهمانان: ${fa(p.guestCount??p.guests??0)}</p><p>منوی سرو: ${escapeHtml(menu.join('، ')||'ثبت نشده')}</p><p>یادداشت: ${escapeHtml(p.notes||'—')}</p></div></article>`}).join(''):'<div class="empty-state">مهمانی مطابق جستجو پیدا نشد. مهمانی‌ها پس از زدن «ذخیره مهمانی» در این آرشیو ثبت می‌شوند.</div>'}
function historyPartyAction(e){const b=e.target.closest('button');if(!b)return;const id=b.dataset.partyDetails||b.dataset.partyLoad||b.dataset.partyDelete;const p=state.parties.find(x=>x.id===id);if(!p)return;if(b.dataset.partyDetails){const panel=$(`#partyDetails-${CSS.escape(id)}`);if(panel)panel.hidden=!panel.hidden;return}if(b.dataset.partyDelete){if(!confirm('این سابقه مهمانی از آرشیو حذف شود؟'))return;state.parties=state.parties.filter(x=>x.id!==id);saveState();renderActivityHistory();renderSavedParties();renderReports();renderDashboard();notify('سابقه مهمانی حذف شد.');return}state.partyMeta={...p};state.partyMenu=[...(p.menu||[])];state.partyGuests=[...(p.guestList||[])];$('#partyName').value=p.name||'';$('#guestCount').value=p.guestCount??p.guests??8;$('#partyDate').value=isoToJalaliInput(p.date);$('#partyMeal').value=p.meal||'ناهار';$('#partyType').value=p.type||'خودمانی';$('#partyStyle').value=p.style||'سنتی';$('#partyBudget').value=p.budget||'';$('#partyNotes').value=p.notes||'';saveState();showView('party');renderPartyMenu();renderGuests();notify('مهمانی برای مشاهده یا ویرایش بارگذاری شد؛ برای ثبت تغییرات «ذخیره مهمانی» را بزنید.')}
function renderMonthlyNutrition(){const el=$('#monthlyNutritionSummary');if(!el)return;const now=new Date(),monthStart=new Date(now.getFullYear(),now.getMonth()-1,1,12),monthEnd=new Date(now.getFullYear(),now.getMonth(),1,12);const from=monthStart.toISOString().slice(0,10),to=new Date(monthEnd.getTime()-86400000).toISOString().slice(0,10);$('#nutritionPeriodLabel').textContent=`دوره بررسی: ${isoToJalaliInput(from)} تا ${isoToJalaliInput(to)} · بر اساس داده‌های ذخیره‌شده`;const recipeById=id=>recipes.find(r=>r.id===id);const archivedWeeks=(state.weekArchives||[]).filter(w=>(w.weekStart||'')>=from&&(w.weekStart||'')<=to);const parties=(state.parties||[]).filter(p=>(p.date||'')>=from&&(p.date||'')<=to);let ids=[];archivedWeeks.forEach(w=>Object.values(w.meals||{}).forEach(day=>Object.values(day||{}).filter(Boolean).forEach(id=>ids.push(id))));parties.forEach(p=>(p.menu||[]).forEach(id=>ids.push(id)));const currentStart=state.weekStart||'';if(currentStart>=from&&currentStart<=to)Object.values(state.weekly||{}).forEach(day=>Object.values(day||{}).filter(Boolean).forEach(id=>ids.push(id)));const used=ids.map(recipeById).filter(Boolean);const traditional=used.filter(r=>(r.tags||[]).includes('traditional')||/قرمه|قورمه|قیمه|آش |آش$|آبگوشت|عدس.?پلو|لوبیا.?پلو|زرشک.?پلو|باقالی.?پلو|ته.?چین|کباب|فسنجان|دلمه|کوکو|کشک.?بادمجان/.test(r.name||'')).length;const healthy=used.filter(r=>(r.tags||[]).some(t=>/healthy|healthy-choice|light|vegetarian|vegan|low-salt|high-protein|organic/i.test(t))||(r.diets||[]).some(t=>/vegetarian|vegan|low-salt|diabetes/i.test(t))||(r.ingredients||[]).some(i=>/سبزی|اسفناج|کلم|بروکلی|عدس|لوبیا|نخود|ماهی|جوپرک/.test(String(i[0])))).length;const organic=used.filter(r=>(r.tags||[]).some(t=>/organic/i.test(t))||(r.ingredients||[]).some(i=>/ارگانیک/.test(String(i[0])))).length;const unique=new Set(used.map(r=>r.id)).size;const categories={};used.forEach(r=>categories[r.category]=(categories[r.category]||0)+1);const categoryText=Object.entries(categories).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`${k}: ${fa(v)}`).join(' · ')||'داده‌ای ثبت نشده';el.innerHTML=`<div class="nutrition-metric-grid"><article><small>وعده‌ها و غذاهای ثبت‌شده</small><b>${fa(used.length)}</b></article><article><small>غذاهای سنتی (تخمینی)</small><b>${fa(traditional)}</b></article><article><small>غذاهای دارای نشانه سالم‌تر</small><b>${fa(healthy)}</b></article><article><small>موارد دارای برچسب ارگانیک</small><b>${fa(organic)}</b></article><article><small>تنوع غذاهای یکتا</small><b>${fa(unique)}</b></article><article><small>مهمانی‌های ثبت‌شده</small><b>${fa(parties.length)}</b></article></div><div class="nutrition-category-summary"><b>ترکیب دسته‌های غذایی</b><p>${escapeHtml(categoryText)}</p></div>`}
async function shareReportItem(type,id){let title='گزارش غذایار',text='';if(type==='shopping'){title='گزارش فهرست خرید غذایار';const items=state.shopping;text=`${title}\nتاریخ: ${isoToJalaliInput(isoToday())}\nتعداد اقلام: ${fa(items.length)}\n${items.map((x,i)=>`${fa(i+1)}. ${x.name} — ${x.qty||'مقدار ثبت نشده'} — ${x.done?'خریداری شده':'باقی‌مانده'}`).join('\n')}`}else if(type==='party'){const p=state.parties.find(x=>x.id===id);if(!p)return;title=`گزارش مهمانی: ${p.name}`;text=`غذایار | ${title}\nتاریخ: ${isoToJalaliInput(p.date)||p.date}\nتعداد مهمان: ${fa(p.guestCount??p.guests??0)}\nوعده: ${p.meal||'—'}\nمنو: ${(p.menu||[]).map(recipeLabel).join('، ')||'ثبت نشده'}\nیادداشت: ${p.notes||'—'}\nپشتیبانی: esmlotfi@gmail.com`}else{let w;if(type==='week-current'||id==='current')w={weekStart:state.weekStart,meals:state.weekly||{}};else w=state.weekArchives.find(x=>x.id===id);if(!w)return;title='گزارش برنامه غذایی هفتگی';const dayNames=['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'];text=`غذایار | ${title}\nشروع هفته: ${isoToJalaliInput(w.weekStart)||w.weekStart}\n`+Object.entries(w.meals||{}).map(([date,day],i)=>`${dayNames[i]||date}: ${MEALS.map(m=>`${m}: ${recipeLabel((day||{})[m])}`).join('، ')}`).join('\n')+`\nپشتیبانی: esmlotfi@gmail.com`}try{if(navigator.share){await navigator.share({title,text});notify('گزارش برای اشتراک‌گذاری آماده شد.')}else if(window.GhazayarNative?.shareText){window.GhazayarNative.shareText(text);notify('پنجره اشتراک‌گذاری باز شد.')}else if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);notify('متن گزارش کپی شد؛ آن را در شبکه اجتماعی دلخواه ارسال کنید.')}else prompt('متن گزارش را کپی کنید:',text)}catch(e){if(e?.name!=='AbortError')prompt('متن گزارش را کپی کنید:',text)}}
function printReportItem(type,id){if(type==='shopping'){printShopping();return}if(type==='party'){const p=state.parties.find(x=>x.id===id);if(!p)return;const menu=(p.menu||[]).map(id=>recipeLabel(id));printHtmlDocument(`گزارش مهمانی: ${p.name}`,`<p>عنوان: ${escapeHtml(p.name)}</p><p>تاریخ: ${escapeHtml(isoToJalaliInput(p.date)||p.date)} · تعداد مهمان: ${fa(p.guestCount??p.guests??0)} · وعده: ${escapeHtml(p.meal||'—')} · نوع: ${escapeHtml(p.type||'—')}</p><h3>منوی انتخاب‌شده</h3><ol>${menu.map(x=>`<li>${escapeHtml(x)}</li>`).join('')||'<li>منویی ثبت نشده است</li>'}</ol><h3>یادداشت</h3><p>${escapeHtml(p.notes||'—')}</p>`);return}if(type==='week-current'||(type==='week'&&id==='current')){printWeeklyDocument({weekStart:state.weekStart,meals:state.weekly||{}},'گزارش برنامه هفتگی فعلی');return}if(type==='week'){const w=state.weekArchives.find(x=>x.id===id);if(!w)return;printWeeklyDocument(w,'گزارش برنامه هفتگی')}}
function printWeeklyDocument(w,title){const dayNames=['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'];const rows=Object.entries(w.meals||{}).map(([date,day],i)=>`<tr class="day-row"><th colspan="2">${dayNames[i]||escapeHtml(date)} <small>(${escapeHtml(isoToJalaliInput(date)||date)})</small></th></tr>${MEALS.map(meal=>`<tr><td class="meal-name">${escapeHtml(meal)}</td><td>${escapeHtml(recipeLabel((day||{})[meal]))}</td></tr>`).join('')}`).join('');printHtmlDocument(title,`<p>هفته آغازشونده: ${escapeHtml(isoToJalaliInput(w.weekStart)||w.weekStart)}</p><table class="weekly-print-table"><tbody>${rows}</tbody></table>`)}
function exportAll(){const lines=[['بخش','تاریخ','عنوان','جزئیات']];state.parties.forEach(p=>lines.push(['مهمانی',p.date,p.name,`${p.guests} مهمان؛ ${p.meal}؛ ${(p.menu||[]).map(id=>recipeLabel(id)).join('، ')}`]));state.weekArchives.forEach(w=>lines.push(['برنامه هفتگی',w.weekStart,'برنامه ذخیره‌شده',JSON.stringify(w.meals)]));state.shopping.forEach(i=>lines.push(['خرید',i.createdAt,i.name,`${i.qty||''}؛ ${i.done?'خریداری شد':'باقی است'}`]));download('ghazayar-report.csv','\ufeff'+csv(lines[0],lines.slice(1)),'text/csv;charset=utf-8');notify('گزارش اطلاعات صادر شد.')}
function csv(headers,rows){return [headers,...rows].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}function backup(){const data={schema:2,exportedAt:new Date().toISOString(),state};download(`ghazayar-backup-${isoToday()}.json`,JSON.stringify(data,null,2),'application/json');notify('فایل پشتیبان آماده شد.')}
function restore(e){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const d=JSON.parse(reader.result);const incoming=d?.state||d;if(!incoming||typeof incoming!=='object'||Array.isArray(incoming))throw Error('invalid');const clean={...cloneDefaultState()};for(const k of Object.keys(clean)){const expected=Array.isArray(clean[k])?'array':typeof clean[k];if(k in incoming){if(expected==='array'&&Array.isArray(incoming[k]))clean[k]=incoming[k];else if(expected==='object'&&incoming[k]&&typeof incoming[k]==='object'&&!Array.isArray(incoming[k]))clean[k]=incoming[k];else if(expected!=='array'&&expected!=='object'&&typeof incoming[k]===expected)clean[k]=incoming[k]}}if(!Array.isArray(clean.family)||!Array.isArray(clean.parties)||!Array.isArray(clean.shopping))throw Error('invalid');state=clean;saveState();renderAll();notify('پشتیبان با موفقیت بازیابی شد.')}catch(err){notify('فایل پشتیبان معتبر نیست؛ اطلاعات قبلی حفظ شد.')}finally{e.target.value=''}};reader.onerror=()=>notify('خواندن فایل ناموفق بود.');reader.readAsText(file)}
// Accessible simple modal alternative for browsers without dialog support.
window.addEventListener('storage',e=>{if(e.key===KEY+'state'){state=loadState();renderAll()}});
document.addEventListener('click',function(e){const nav=e.target.closest('[data-view]');if(nav){showView(nav.dataset.view);return}const go=e.target.closest('[data-goto]');if(go){showView(go.dataset.goto);return}const details=e.target.closest('[data-recipe-details]');if(details){openRecipe(details.dataset.recipeDetails);return}const save=e.target.closest('[data-recipe-save]');if(save){recipeGridAction({target:save});return}});document.addEventListener('input',function(e){if(e.target&&e.target.id==='recipeSearch')renderRecipes()});document.addEventListener('change',function(e){if(e.target&&['recipeCategory','dietFilter','timeFilter'].includes(e.target.id))renderRecipes()});document.addEventListener('DOMContentLoaded',init);
